insert into public.recipes (id, name, description, categories, cuisine, servings, prep_minutes, cook_minutes, difficulty, created_at, updated_at) values
  ('ciorba-de-perisoare', 'Ciorbă de perișoare', 'Ciorbă acrită cu borș, cu perișoare fragede din carne tocată și orez și multă verdeață.', array['supe_ciorbe', 'traditionale', 'pranz', 'carne']::text[], 'romaneasca', 6, 30, 50, 'mediu', '2026-10-12T03:00:00.000Z', '2026-10-12T03:00:00.000Z'),
  ('ciorba-de-legume', 'Ciorbă de legume', 'O ciorbă ușoară, acrită cu borș, plină de legume de sezon. Bună pentru zilele de post sau când vrei ceva fără carne.', array['supe_ciorbe', 'traditionale', 'pranz', 'vegetariene']::text[], 'romaneasca', 6, 20, 40, 'usor', '2026-10-12T03:00:00.000Z', '2026-10-12T03:00:00.000Z'),
  ('ciorba-de-pui', 'Ciorbă de pui a la grec', 'Ciorbă de pui cu orez, îngroșată cu ou și lămâie, fină și mătăsoasă. O ai pe masă în aproape o oră.', array['supe_ciorbe', 'pranz', 'carne']::text[], 'internationala', 6, 15, 45, 'mediu', '2026-10-12T03:00:00.000Z', '2026-10-12T03:00:00.000Z'),
  ('supa-de-pui-cu-taitei', 'Supă de pui cu tăiței', 'Supa limpede de duminică, cu tăiței fini și legume. Caldă și liniștitoare, pentru toată familia.', array['supe_ciorbe', 'pranz', 'carne']::text[], 'romaneasca', 6, 15, 60, 'usor', '2026-10-12T03:00:00.000Z', '2026-10-12T03:00:00.000Z'),
  ('ciorba-de-fasole-cu-afumatura', 'Ciorbă de fasole cu afumătură', 'Ciorbă groasă de fasole boabe, cu costiță afumată și boia. Se face în timp, dar merită așteptarea.', array['supe_ciorbe', 'traditionale', 'pranz', 'carne']::text[], 'romaneasca', 6, 20, 120, 'mediu', '2026-10-12T03:00:00.000Z', '2026-10-12T03:00:00.000Z'),
  ('ciorba-de-vacuta', 'Ciorbă de văcuță', 'Ciorbă din carne de vită, cu legume și borș, cu gust bogat și curat. Se fierbe încet până carnea se desface singură.', array['supe_ciorbe', 'traditionale', 'pranz', 'carne']::text[], 'romaneasca', 6, 20, 100, 'mediu', '2026-10-12T03:00:00.000Z', '2026-10-12T03:00:00.000Z'),
  ('ciorba-de-loboda', 'Ciorbă de lobodă', 'O ciorbă de primăvară, verde și răcoroasă, acrită ușor cu borș. Merge bine și fără carne.', array['supe_ciorbe', 'traditionale', 'pranz', 'vegetariene']::text[], 'romaneasca', 6, 15, 30, 'usor', '2026-10-12T03:00:00.000Z', '2026-10-12T03:00:00.000Z'),
  ('supa-crema-de-dovleac', 'Supă cremă de dovleac', 'Supă cremoasă și dulceagă de dovleac, bună în zilele răcoroase. Se mixează într-o clipă.', array['supe_ciorbe', 'pranz', 'vegetariene']::text[], 'internationala', 6, 15, 30, 'usor', '2026-10-12T03:00:00.000Z', '2026-10-12T03:00:00.000Z'),
  ('supa-crema-de-legume', 'Supă cremă de legume', 'Supă fină, făcută din legumele pe care le ai prin casă. Prinde bine și când vrei ceva ușor.', array['supe_ciorbe', 'pranz', 'vegetariene']::text[], 'internationala', 6, 15, 30, 'usor', '2026-10-12T03:00:00.000Z', '2026-10-12T03:00:00.000Z'),
  ('supa-de-rosii', 'Supă de roșii', 'Supă de roșii cu gust bun de vară, fină și ușor dulceagă. Merge bine cu crutoane sau cu un strop de smântână.', array['supe_ciorbe', 'pranz', 'vegetariene']::text[], 'internationala', 4, 10, 30, 'usor', '2026-10-12T03:00:00.000Z', '2026-10-12T03:00:00.000Z'),
  ('bors-de-peste', 'Borș de pește', 'Borș tradițional cu pește de apă dulce, legume și leuștean, acrit cu borș. Clasic pentru zilele de post.', array['supe_ciorbe', 'traditionale', 'pranz', 'peste']::text[], 'romaneasca', 6, 25, 50, 'mediu', '2026-10-12T03:00:00.000Z', '2026-10-12T03:00:00.000Z'),
  ('supa-de-galuste', 'Supă de găluște', 'Supă de pui cu găluște pufoase de gris, o rețetă simplă din copilărie. Găluștele se fac repede, cu două ingrediente la îndemână.', array['supe_ciorbe', 'traditionale', 'pranz', 'carne']::text[], 'romaneasca', 6, 20, 60, 'mediu', '2026-10-12T03:00:00.000Z', '2026-10-12T03:00:00.000Z'),
  ('ciorba-taraneasca-de-porc', 'Ciorbă țărănească de porc', 'Ciorbă consistentă, cu carne de porc și legume, acrită cu borș. O masă întreagă într-o singură oală.', array['supe_ciorbe', 'traditionale', 'pranz', 'carne']::text[], 'romaneasca', 6, 20, 75, 'mediu', '2026-10-12T03:00:00.000Z', '2026-10-12T03:00:00.000Z'),
  ('omleta-cu-legume', 'Omletă cu legume', 'Omletă pufoasă cu legume, bună pentru un mic dejun consistent. Se face dintr-o singură tigaie.', array['mic_dejun', 'rapide', 'vegetariene']::text[], 'internationala', 2, 10, 10, 'usor', '2026-10-12T03:00:00.000Z', '2026-10-12T03:00:00.000Z'),
  ('oua-ochiuri', 'Ouă ochiuri cu pâine prăjită', 'Mic dejun simplu: ouă ochiuri cu gălbenușul moale și pâine prăjită crocantă. Gata în câteva minute.', array['mic_dejun', 'rapide', 'vegetariene']::text[], 'romaneasca', 2, 5, 8, 'usor', '2026-10-12T03:00:00.000Z', '2026-10-12T03:00:00.000Z'),
  ('salata-de-oua', 'Salată de ouă', 'Salată de ouă fierte cu iaurt și muștar, bună pe pâine sau ca pachet de prânz. O pregătești din timp și ține în frigider.', array['mic_dejun', 'salate', 'rapide', 'vegetariene']::text[], 'internationala', 4, 10, 10, 'usor', '2026-10-12T03:00:00.000Z', '2026-10-12T03:00:00.000Z'),
  ('terci-de-ovaz-cu-fructe', 'Terci de ovăz cu fructe', 'Terci cald de ovăz, cu lapte, fructe și puțină miere. Mic dejun care te ține sătul până la prânz.', array['mic_dejun', 'rapide', 'vegetariene']::text[], 'internationala', 2, 5, 10, 'usor', '2026-10-12T03:00:00.000Z', '2026-10-12T03:00:00.000Z'),
  ('clatite', 'Clătite', 'Clătite subțiri și moi, bune cu dulceață, brânză sau miere. Aluatul se face repede, din ingrediente simple.', array['mic_dejun', 'deserturi', 'vegetariene']::text[], 'romaneasca', 4, 15, 20, 'usor', '2026-10-12T03:00:00.000Z', '2026-10-12T03:00:00.000Z'),
  ('sandvis-cu-branza-si-legume', 'Sandviș cu brânză și legume', 'Sandviș rapid, cu brânză proaspătă și legume crocante. Bun pentru dimineață sau pentru pachet.', array['mic_dejun', 'gustari', 'rapide', 'vegetariene']::text[], 'internationala', 2, 10, 0, 'usor', '2026-10-12T03:00:00.000Z', '2026-10-12T03:00:00.000Z'),
  ('bulz', 'Bulz ciobănesc', 'Bulz de mămăligă cu brânză în mijloc, copt până se rumenește. O rețetă de la munte, simplă și sățioasă.', array['traditionale', 'pranz', 'vegetariene']::text[], 'romaneasca', 4, 15, 45, 'mediu', '2026-10-12T03:00:00.000Z', '2026-10-12T03:00:00.000Z'),
  ('gris-cu-lapte', 'Griș cu lapte', 'Griș cu lapte fierbinte, fin și dulce, ca în copilărie. Se face în 10 minute, cu dulceață sau scorțișoară deasupra.', array['mic_dejun', 'rapide', 'vegetariene']::text[], 'romaneasca', 2, 3, 10, 'usor', '2026-10-12T03:00:00.000Z', '2026-10-12T03:00:00.000Z'),
  ('iaurt-cu-musli-si-fructe', 'Iaurt cu musli și fructe', 'Mic dejun răcoros, fără gătit: iaurt cu musli crocant și fructe. Îl poți pregăti în două minute.', array['mic_dejun', 'rapide', 'vegetariene']::text[], 'internationala', 2, 5, 0, 'usor', '2026-10-12T03:00:00.000Z', '2026-10-12T03:00:00.000Z'),
  ('ochiuri-romanesti-scrob', 'Scrob cu ceapă verde', 'Ouă jumări cu ceapă verde multă, în stil de casă. Gata în câteva minute, cu pâine proaspătă alături.', array['mic_dejun', 'traditionale', 'rapide', 'vegetariene']::text[], 'romaneasca', 2, 5, 10, 'usor', '2026-10-12T03:00:00.000Z', '2026-10-12T03:00:00.000Z'),
  ('sarmale', 'Sarmale în foi de varză murată', 'Sarmale moi, cu carne și orez, fierte încet pe pat de varză murată. Se păstrează bine și sunt și mai bune a doua zi.', array['traditionale', 'pranz', 'carne', 'meal_prep']::text[], 'romaneasca', 8, 60, 120, 'dificil', '2026-10-12T03:00:00.000Z', '2026-10-12T03:00:00.000Z'),
  ('ardei-umpluti', 'Ardei umpluți', 'Ardei grași umpluți cu carne și orez, fierți în sos de roșii. O mâncare de familie, simplă și sățioasă.', array['traditionale', 'pranz', 'carne']::text[], 'romaneasca', 6, 40, 60, 'mediu', '2026-10-12T03:00:00.000Z', '2026-10-12T03:00:00.000Z'),
  ('tocanita-de-porc', 'Tocăniță de porc', 'Carne de porc înăbușită încet cu ceapă și roșii, până devine fragedă. Merge de minune cu mămăligă.', array['traditionale', 'pranz', 'cina', 'carne', 'meal_prep']::text[], 'romaneasca', 5, 20, 90, 'mediu', '2026-10-12T03:00:00.000Z', '2026-10-12T03:00:00.000Z'),
  ('ostropel-de-pui', 'Ostropel de pui', 'Pui fiert în sos de roșii cu mult usturoi, cum se făcea la țară. Se mănâncă cu mămăligă caldă.', array['traditionale', 'pranz', 'cina', 'carne']::text[], 'romaneasca', 4, 20, 60, 'mediu', '2026-10-12T03:00:00.000Z', '2026-10-12T03:00:00.000Z'),
  ('pilaf-de-pui', 'Pilaf de pui', 'Orez fiert în supă împreună cu bucăți de pui rumenit. O mâncare dintr-o singură oală, ușor de făcut.', array['traditionale', 'pranz', 'cina', 'carne']::text[], 'romaneasca', 4, 15, 40, 'usor', '2026-10-12T03:00:00.000Z', '2026-10-12T03:00:00.000Z'),
  ('mancare-de-fasole-cu-carnati', 'Mâncare de fasole cu cârnați', 'Fasole boabe fiartă încet, cu ceapă și cârnați afumați. O mâncare grea și bună pentru zilele reci.', array['traditionale', 'pranz', 'carne', 'meal_prep']::text[], 'romaneasca', 6, 20, 120, 'mediu', '2026-10-12T03:00:00.000Z', '2026-10-12T03:00:00.000Z'),
  ('ghiveci-de-legume', 'Ghiveci de legume', 'Legume de sezon coapte lent în sos de roșii, la cuptor. Se face ușor și e bun cald sau rece.', array['traditionale', 'pranz', 'cina', 'vegetariene', 'meal_prep']::text[], 'romaneasca', 6, 30, 75, 'usor', '2026-10-12T03:00:00.000Z', '2026-10-12T03:00:00.000Z'),
  ('chiftele-de-porc-vita', 'Chiftele', 'Chiftele crocante pe dinafară și fragede înăuntru, din carne de porc și vită. Se servesc cu piure sau salată.', array['traditionale', 'pranz', 'cina', 'carne']::text[], 'romaneasca', 4, 25, 20, 'usor', '2026-10-12T03:00:00.000Z', '2026-10-12T03:00:00.000Z'),
  ('mamaliga-cu-branza-si-smantana', 'Mămăligă cu brânză și smântână', 'Mămăligă caldă, cu brânză sărată și smântână, simplă și potrivită oricând. Merge și ca garnitură.', array['traditionale', 'pranz', 'cina', 'vegetariene']::text[], 'romaneasca', 4, 5, 30, 'usor', '2026-10-12T03:00:00.000Z', '2026-10-12T03:00:00.000Z'),
  ('tochitura-moldoveneasca', 'Tochitură moldovenească', 'Carne de porc și cârnați într-un sos aromat cu vin, servite cu mămăligă și ou ochi. Tradițională din Moldova.', array['traditionale', 'pranz', 'cina', 'carne']::text[], 'romaneasca', 4, 20, 60, 'mediu', '2026-10-12T03:00:00.000Z', '2026-10-12T03:00:00.000Z'),
  ('varza-calita-cu-carne', 'Varză călită cu carne de porc', 'Varză albă înăbușită cu carne de porc, ceapă și puțin bulion. O mâncare simplă, bună la prânz.', array['traditionale', 'pranz', 'cina', 'carne']::text[], 'romaneasca', 5, 25, 70, 'mediu', '2026-10-12T03:00:00.000Z', '2026-10-12T03:00:00.000Z'),
  ('musaca-de-cartofi', 'Musaca de cartofi', 'Straturi de cartofi și carne tocată, coapte cu un topping de ou și smântână. Se taie ușor în felii.', array['traditionale', 'pranz', 'cina', 'carne']::text[], 'romaneasca', 6, 40, 60, 'mediu', '2026-10-12T03:00:00.000Z', '2026-10-12T03:00:00.000Z'),
  ('friptura-de-porc-la-tava', 'Friptură de porc la tavă', 'Friptură de porc coaptă încet la cuptor, cu cartofi și usturoi. Iese suculentă și frumos rumenită.', array['traditionale', 'pranz', 'carne']::text[], 'romaneasca', 6, 20, 120, 'mediu', '2026-10-12T03:00:00.000Z', '2026-10-12T03:00:00.000Z'),
  ('pui-la-cuptor-cu-cartofi', 'Pulpe de pui la cuptor cu cartofi', 'Pulpe de pui crocante, coapte pe un pat de cartofi cu usturoi și boia. Merge bine pentru o masă în familie.', array['traditionale', 'pranz', 'cina', 'carne']::text[], 'romaneasca', 4, 15, 60, 'usor', '2026-10-12T03:00:00.000Z', '2026-10-12T03:00:00.000Z'),
  ('mancare-de-mazare-cu-pui', 'Mâncare de mazăre cu pui', 'Mazăre verde fiartă ușor cu bucăți de pui, morcov și mărar. O mâncare fragedă, de primăvară.', array['traditionale', 'pranz', 'cina', 'carne']::text[], 'romaneasca', 4, 15, 45, 'usor', '2026-10-12T03:00:00.000Z', '2026-10-12T03:00:00.000Z'),
  ('tocana-de-cartofi', 'Tocană de cartofi', 'Cartofi fierți în sos de roșii cu ceapă și boia, la care poți adăuga cârnați. O mâncare caldă, ieftină și bună.', array['traditionale', 'pranz', 'cina', 'vegetariene']::text[], 'romaneasca', 4, 15, 35, 'usor', '2026-10-12T03:00:00.000Z', '2026-10-12T03:00:00.000Z'),
  ('papricas-de-pui', 'Papricaș de pui', 'Pui fraged într-un sos cremos de boia dulce și smântână. Se servește cu mămăligă sau găluște.', array['traditionale', 'pranz', 'cina', 'carne']::text[], 'romaneasca', 4, 20, 50, 'mediu', '2026-10-12T03:00:00.000Z', '2026-10-12T03:00:00.000Z'),
  ('ciulama-de-pui-cu-ciuperci', 'Ciulama de pui cu ciuperci', 'Pui și ciuperci într-un sos alb, fin, cu lapte și smântână. Se mănâncă bine cu mămăligă.', array['traditionale', 'pranz', 'cina', 'carne']::text[], 'romaneasca', 4, 15, 40, 'mediu', '2026-10-12T03:00:00.000Z', '2026-10-12T03:00:00.000Z'),
  ('iahnie-de-fasole', 'Iahnie de fasole', 'Fasole boabe într-un sos gros de ceapă călită, cu boia și dafin. O mâncare de post, sățioasă.', array['traditionale', 'pranz', 'cina', 'vegetariene', 'meal_prep']::text[], 'romaneasca', 6, 20, 100, 'usor', '2026-10-12T03:00:00.000Z', '2026-10-12T03:00:00.000Z'),
  ('mici-la-gratar', 'Mici la grătar cu muștar', 'Mici sfârâitori, făcuți din carne tocată și condimentați cu usturoi și cimbru. Se servesc cu muștar și pâine.', array['traditionale', 'pranz', 'cina', 'carne']::text[], 'romaneasca', 4, 20, 15, 'mediu', '2026-10-12T03:00:00.000Z', '2026-10-12T03:00:00.000Z'),
  ('drob-de-miel', 'Drob de miel', 'Drob de Paște, cu organe de miel, ouă fierte și verdeață, copt în tavă. Se taie felii când s-a răcit.', array['traditionale', 'pranz', 'carne']::text[], 'romaneasca', 8, 40, 70, 'dificil', '2026-10-12T03:00:00.000Z', '2026-10-12T03:00:00.000Z'),
  ('peste-la-cuptor-cu-legume', 'Pește la cuptor cu legume', 'File de merluciu copt pe un pat de cartofi, ardei și roșii. O tavă și o cină gata fără prea multă bătaie de cap.', array['peste', 'pranz', 'cina']::text[], 'romaneasca', 4, 20, 40, 'usor', '2026-10-12T03:00:00.000Z', '2026-10-12T03:00:00.000Z'),
  ('saramura-de-crap', 'Saramură de crap', 'Crap rumenit la grătar sau în tigaie, înecat într-o saramură iute cu usturoi. Se servește cu mămăligă fierbinte.', array['peste', 'traditionale', 'pranz']::text[], 'romaneasca', 4, 20, 40, 'mediu', '2026-10-12T03:00:00.000Z', '2026-10-12T03:00:00.000Z'),
  ('pastrav-la-gratar', 'Păstrăv la grătar cu mujdei', 'Păstrăvi întregi cu coaja crocantă și carnea fragedă, serviți cu mujdei de usturoi și lămâie.', array['peste', 'pranz', 'cina']::text[], 'romaneasca', 4, 20, 20, 'mediu', '2026-10-12T03:00:00.000Z', '2026-10-12T03:00:00.000Z'),
  ('somon-la-cuptor-cu-lamaie', 'Somon la cuptor cu lămâie și legume', 'Somon suculent cu lămâie și mărar, copt împreună cu cartofi noi și broccoli. Se face repede și arată bine pe masă.', array['peste', 'cina', 'pranz']::text[], 'internationala', 4, 15, 25, 'usor', '2026-10-12T03:00:00.000Z', '2026-10-12T03:00:00.000Z'),
  ('file-de-cod-cu-piure', 'File de cod cu piure de cartofi', 'Cod fraged, rumenit în tigaie, alături de un piure cremos cu unt. Mâncare simplă, pe gustul întregii familii.', array['peste', 'pranz', 'cina']::text[], 'internationala', 4, 15, 30, 'usor', '2026-10-12T03:00:00.000Z', '2026-10-12T03:00:00.000Z'),
  ('macrou-la-cuptor', 'Macrou la cuptor', 'Macrou copt întreg cu ceapă, roșii și lămâie. Pielea se rumenește frumos, iar carnea rămâne gustoasă.', array['peste', 'pranz', 'cina']::text[], 'romaneasca', 4, 15, 35, 'usor', '2026-10-12T03:00:00.000Z', '2026-10-12T03:00:00.000Z'),
  ('salata-de-vinete', 'Salată de vinete', 'Vinete coapte pe jar sau în cuptor, tocate fin și frecate cu ulei și ceapă. Se întinde pe pâine sau se servește lângă friptură.', array['salate', 'gustari', 'traditionale', 'vegetariene', 'meal_prep']::text[], 'romaneasca', 4, 20, 40, 'usor', '2026-10-12T03:00:00.000Z', '2026-10-12T03:00:00.000Z'),
  ('salata-de-boeuf', 'Salată de boeuf', 'Legume fierte, pui și murături tăiate cubulețe, legate cu maioneză. O salată de sărbătoare, dar și o masă bună în zilele obișnuite.', array['salate', 'traditionale', 'meal_prep']::text[], 'romaneasca', 6, 30, 40, 'mediu', '2026-10-12T03:00:00.000Z', '2026-10-12T03:00:00.000Z'),
  ('salata-de-rosii-cu-castraveti', 'Salată de roșii cu castraveți și ceapă', 'Salata de vară pe care o faci în zece minute: roșii coapte, castraveți crocanți și ceapă, cu ulei și oțet.', array['salate', 'vegetariene', 'rapide']::text[], 'romaneasca', 4, 10, 0, 'usor', '2026-10-12T03:00:00.000Z', '2026-10-12T03:00:00.000Z'),
  ('salata-de-varza', 'Salată de varză albă', 'Varză albă tăiată fin, cu morcov, ulei și oțet. Crocantă, ieftină și bună lângă orice friptură.', array['salate', 'vegetariene', 'rapide']::text[], 'romaneasca', 4, 15, 0, 'usor', '2026-10-12T03:00:00.000Z', '2026-10-12T03:00:00.000Z'),
  ('salata-orientala', 'Salată orientală de cartofi', 'Cartofi fierți, ceapă, ouă și măsline, cu ulei și oțet. Se face ușor și merge bine cu pește sau singură.', array['salate', 'vegetariene', 'traditionale']::text[], 'romaneasca', 4, 15, 30, 'usor', '2026-10-12T03:00:00.000Z', '2026-10-12T03:00:00.000Z'),
  ('salata-de-fasole-verde', 'Salată de fasole verde cu usturoi', 'Fasole verde fiartă scurt, ca să rămână crocantă, amestecată cu usturoi, ulei și oțet. Se mănâncă și caldă, și rece.', array['salate', 'vegetariene', 'rapide', 'meal_prep']::text[], 'romaneasca', 4, 10, 10, 'usor', '2026-10-12T03:00:00.000Z', '2026-10-12T03:00:00.000Z'),
  ('salata-greceasca', 'Salată grecească', 'Roșii, castraveți, ardei și ceapă roșie, cu măsline și un cub mare de feta deasupra. Proaspătă și plină de gust.', array['salate', 'vegetariene', 'rapide']::text[], 'internationala', 4, 15, 0, 'usor', '2026-10-12T03:00:00.000Z', '2026-10-12T03:00:00.000Z'),
  ('dovlecei-pane', 'Dovlecei pane', 'Felii de dovlecei trecute prin ou și pesmet, prăjite aurii. Se servesc cu iaurt sau cu un sos de usturoi.', array['vegetariene', 'pranz', 'cina']::text[], 'romaneasca', 4, 20, 20, 'usor', '2026-10-12T03:00:00.000Z', '2026-10-12T03:00:00.000Z'),
  ('chiftele-de-dovlecei', 'Chiftele de dovlecei', 'Chiftele pufoase din dovlecei rași, cu telemea și mărar. Bune calde sau reci, cu un iaurt alături.', array['vegetariene', 'pranz', 'cina', 'gustari']::text[], 'romaneasca', 4, 20, 20, 'usor', '2026-10-12T03:00:00.000Z', '2026-10-12T03:00:00.000Z'),
  ('mancare-de-spanac', 'Mâncare de spanac cu usturoi', 'Spanac fiert încet cu ceai de făină rumenită și mult usturoi. Rețetă de post, simplă, bună cu mămăligă sau cu ou ochi.', array['traditionale', 'vegetariene', 'pranz']::text[], 'romaneasca', 4, 15, 25, 'usor', '2026-10-12T03:00:00.000Z', '2026-10-12T03:00:00.000Z'),
  ('cartofi-taranesti', 'Cartofi țărănești', 'Cartofi copți în tigaie sau în tavă, cu ceapă, boia și usturoi. Mâncare simplă care se termină repede din farfurie.', array['traditionale', 'vegetariene', 'pranz', 'cina']::text[], 'romaneasca', 4, 15, 35, 'usor', '2026-10-12T03:00:00.000Z', '2026-10-12T03:00:00.000Z'),
  ('linte-cu-legume', 'Linte cu legume', 'Linte fiartă cu morcov, țelină și ceapă, într-un sos de roșii cu dafin. O masă sățioasă care se păstrează bine pentru zilele următoare.', array['vegetariene', 'pranz', 'meal_prep']::text[], 'romaneasca', 4, 15, 40, 'usor', '2026-10-12T03:00:00.000Z', '2026-10-12T03:00:00.000Z'),
  ('fasole-batuta', 'Fasole bătută cu ceapă călită', 'Piure de fasole fiartă, legat cu ulei și usturoi, cu ceapă călită deasupra. Un clasic de post, bun cu murături.', array['traditionale', 'vegetariene', 'gustari', 'pranz', 'meal_prep']::text[], 'romaneasca', 4, 20, 90, 'mediu', '2026-10-12T03:00:00.000Z', '2026-10-12T03:00:00.000Z'),
  ('ciuperci-cu-smantana', 'Ciuperci cu smântână și mămăligă', 'Ciuperci călite cu ceapă și usturoi, legate cu smântână și mărar. Se servesc peste mămăligă caldă.', array['vegetariene', 'pranz', 'cina']::text[], 'romaneasca', 4, 15, 30, 'usor', '2026-10-12T03:00:00.000Z', '2026-10-12T03:00:00.000Z'),
  ('vinete-la-cuptor-cu-rosii', 'Vinete la cuptor cu roșii și brânză', 'Vinete tăiate pe lung, coapte cu roșii, usturoi și cașcaval topit. Mâncare ușoară, bună cu pâine.', array['vegetariene', 'pranz', 'cina']::text[], 'romaneasca', 4, 20, 40, 'usor', '2026-10-12T03:00:00.000Z', '2026-10-12T03:00:00.000Z'),
  ('spaghete-bolognese', 'Spaghete bolognese', 'Spaghete cu un sos de carne tocată gătit încet, cu roșii și legume. Se face ușor și se mănâncă cu poftă de toată familia.', array['pranz', 'cina', 'carne']::text[], 'internationala', 4, 15, 50, 'usor', '2026-10-12T03:00:00.000Z', '2026-10-12T03:00:00.000Z'),
  ('paste-carbonara', 'Paste carbonara', 'Paste cu bacon, ou și parmezan, într-un sos cremos făcut fără smântână. Sunt gata în douăzeci de minute.', array['pranz', 'cina', 'carne', 'rapide']::text[], 'internationala', 4, 10, 15, 'mediu', '2026-10-12T03:00:00.000Z', '2026-10-12T03:00:00.000Z'),
  ('lasagna', 'Lasagna cu carne', 'Straturi de foi de lasagna, sos de carne și sos alb, gratinate cu mozzarella. O masă pentru o duminică în familie.', array['pranz', 'cina', 'carne']::text[], 'internationala', 6, 40, 60, 'mediu', '2026-10-12T03:00:00.000Z', '2026-10-12T03:00:00.000Z'),
  ('pizza-de-casa', 'Pizza de casă', 'Aluat pufos făcut acasă, cu sos de roșii și mozzarella. Din cantitatea de mai jos ies două pizze mari.', array['pranz', 'cina', 'vegetariene']::text[], 'internationala', 4, 30, 15, 'mediu', '2026-10-12T03:00:00.000Z', '2026-10-12T03:00:00.000Z'),
  ('chili-con-carne', 'Chili con carne', 'Tocăniță de carne tocată cu fasole și roșii, bine condimentată. Se servește cu orez sau cu pâine.', array['pranz', 'cina', 'carne']::text[], 'internationala', 4, 15, 45, 'usor', '2026-10-12T03:00:00.000Z', '2026-10-12T03:00:00.000Z'),
  ('curry-de-pui', 'Curry de pui cu orez', 'Pui în sos de roșii cu curry, ghimbir și smântână, servit peste orez fiert. Un fel de mâncare cald și aromat.', array['pranz', 'cina', 'carne']::text[], 'internationala', 4, 15, 35, 'usor', '2026-10-12T03:00:00.000Z', '2026-10-12T03:00:00.000Z'),
  ('risotto-cu-ciuperci', 'Risotto cu ciuperci', 'Orez cremos gătit încet în supă, cu ciuperci călite și parmezan. Cere puțină răbdare și amestecat des.', array['pranz', 'cina', 'vegetariene']::text[], 'internationala', 4, 15, 30, 'mediu', '2026-10-12T03:00:00.000Z', '2026-10-12T03:00:00.000Z'),
  ('paste-cu-ton-si-rosii', 'Paste cu ton și roșii', 'Paste rapide, cu sos de roșii, ton și măsline. Bune pentru o seară în care nu ai timp de gătit mult.', array['pranz', 'cina', 'peste', 'rapide']::text[], 'internationala', 4, 10, 15, 'usor', '2026-10-12T03:00:00.000Z', '2026-10-12T03:00:00.000Z'),
  ('salata-caesar-cu-pui', 'Salată Caesar cu pui', 'Salată verde cu pui la tigaie, crutoane crocante și un dressing cremos cu parmezan. Merge ca masă de sine stătătoare.', array['pranz', 'cina', 'salate', 'carne', 'rapide']::text[], 'internationala', 4, 15, 12, 'usor', '2026-10-12T03:00:00.000Z', '2026-10-12T03:00:00.000Z'),
  ('hummus', 'Hummus', 'Cremă de năut cu lămâie și usturoi, bună pe pâine, lipie sau cu crudități. Năutul se pune la înmuiat din seara dinainte.', array['gustari', 'vegetariene']::text[], 'internationala', 6, 15, 60, 'usor', '2026-10-12T03:00:00.000Z', '2026-10-12T03:00:00.000Z'),
  ('bowl-cu-pui-si-orez', 'Bol cu pui, orez și legume — meal prep', 'Pui la cuptor, orez și legume coapte, împărțite în caserole pentru patru zile. Îți scutește mesele de la prânz.', array['pranz', 'carne', 'meal_prep']::text[], 'internationala', 4, 20, 30, 'usor', '2026-10-12T03:00:00.000Z', '2026-10-12T03:00:00.000Z'),
  ('chiftele-la-cuptor-meal-prep', 'Chiftele la cuptor cu legume — meal prep', 'Chiftele coapte pe aceeași tavă cu cartofi, morcovi și dovlecei. Se pun în caserole și țin bine 3–4 zile la frigider.', array['pranz', 'cina', 'carne', 'meal_prep']::text[], 'internationala', 4, 25, 40, 'usor', '2026-10-12T03:00:00.000Z', '2026-10-12T03:00:00.000Z'),
  ('quesadilla-cu-pui', 'Quesadilla cu pui', 'Lipii umplute cu pui, cașcaval și legume, rumenite în tigaie. Se fac repede și se mănâncă cu mâna.', array['pranz', 'cina', 'carne', 'rapide']::text[], 'internationala', 4, 15, 15, 'usor', '2026-10-12T03:00:00.000Z', '2026-10-12T03:00:00.000Z'),
  ('papanasi', 'Papanași cu smântână și dulceață', 'Gogoși din brânză de vaci, prăjite aurii și servite cu smântână și dulceață. Din cantitatea de mai jos ies cam 12 bucăți.', array['deserturi', 'traditionale']::text[], 'romaneasca', 6, 25, 20, 'mediu', '2026-10-12T03:00:00.000Z', '2026-10-12T03:00:00.000Z'),
  ('placinta-cu-mere', 'Plăcintă cu mere', 'Aluat fraged cu unt, umplut cu mere rase și scorțișoară. Miroase de te cheamă în bucătărie.', array['deserturi', 'traditionale']::text[], 'romaneasca', 8, 40, 45, 'mediu', '2026-10-12T03:00:00.000Z', '2026-10-12T03:00:00.000Z'),
  ('chec-cu-cacao', 'Chec marmorat', 'Chec pufos cu două culori, vanilie și cacao. Se taie în 10 felii și ține bine câteva zile.', array['deserturi', 'traditionale']::text[], 'romaneasca', 10, 20, 50, 'usor', '2026-10-12T03:00:00.000Z', '2026-10-12T03:00:00.000Z'),
  ('orez-cu-lapte', 'Orez cu lapte și scorțișoară', 'Orez fiert încet în lapte, cu vanilie și scorțișoară deasupra. Un desert simplu, bun și cald, și rece.', array['deserturi', 'traditionale']::text[], 'romaneasca', 4, 5, 35, 'usor', '2026-10-12T03:00:00.000Z', '2026-10-12T03:00:00.000Z'),
  ('salata-de-fructe', 'Salată de fructe', 'Fructe proaspete tăiate cubulețe, cu zeamă de lămâie și puțină miere. Se face în cincisprezece minute.', array['deserturi', 'salate', 'rapide']::text[], 'internationala', 4, 15, 0, 'usor', '2026-10-12T03:00:00.000Z', '2026-10-12T03:00:00.000Z'),
  ('placinta-cu-branza', 'Plăcintă cu brânză dulce', 'Foi subțiri unse cu unt, umplute cu brânză dulce de vaci și stafide. Se rumenește frumos în tavă.', array['deserturi', 'traditionale']::text[], 'romaneasca', 8, 30, 40, 'mediu', '2026-10-12T03:00:00.000Z', '2026-10-12T03:00:00.000Z'),
  ('briose-cu-afine', 'Brioșe cu afine', 'Brioșe moi, cu afine întregi în aluat. Din cantitatea de mai jos ies 12 bucăți.', array['deserturi']::text[], 'internationala', 12, 15, 22, 'usor', '2026-10-12T03:00:00.000Z', '2026-10-12T03:00:00.000Z'),
  ('cozonac-de-casa', 'Cozonac cu nucă și cacao', 'Cozonac pufos, cu umplutură de nucă și cacao. Cere timp de dospit, dar mare parte din el stai liber.', array['deserturi', 'traditionale']::text[], 'romaneasca', 12, 60, 50, 'dificil', '2026-10-12T03:00:00.000Z', '2026-10-12T03:00:00.000Z')
