insert into public.recipe_steps (id, recipe_id, position, text, created_at, updated_at) values
  ('ciorba-de-perisoare:s1', 'ciorba-de-perisoare', 0, 'Toacă mărunt o ceapă și amestec-o cu carnea tocată, orezul spălat, oul, jumătate din pătrunjelul tocat, sare și piper.', '2026-10-12T03:00:00.000Z', '2026-10-12T03:00:00.000Z'),
  ('ciorba-de-perisoare:s2', 'ciorba-de-perisoare', 1, 'Pune la fiert 2,5 l de apă cu sare. Adaugă ceapa rămasă, morcovii, ardeiul, țelina și păstârnacul tăiate cubulețe și fierbe 15 minute.', '2026-10-12T03:00:00.000Z', '2026-10-12T03:00:00.000Z'),
  ('ciorba-de-perisoare:s3', 'ciorba-de-perisoare', 2, 'Cu mâinile ude, formează perișoare cât o nucă și pune-le pe rând în ciorba care clocotește.', '2026-10-12T03:00:00.000Z', '2026-10-12T03:00:00.000Z'),
  ('ciorba-de-perisoare:s4', 'ciorba-de-perisoare', 3, 'Fierbe la foc mic 25–30 de minute, până se înmoaie orezul din perișoare.', '2026-10-12T03:00:00.000Z', '2026-10-12T03:00:00.000Z'),
  ('ciorba-de-perisoare:s5', 'ciorba-de-perisoare', 4, 'Adaugă bulionul și borșul fiert separat, apoi mai fierbe 5 minute.', '2026-10-12T03:00:00.000Z', '2026-10-12T03:00:00.000Z'),
  ('ciorba-de-perisoare:s6', 'ciorba-de-perisoare', 5, 'Stinge focul, potrivește de sare și presară leușteanul și restul de verdeață tocată.', '2026-10-12T03:00:00.000Z', '2026-10-12T03:00:00.000Z'),
  ('ciorba-de-legume:s1', 'ciorba-de-legume', 0, 'Curăță legumele și taie-le cubulețe: ceapa, morcovii, păstârnacul, țelina, ardeiul, cartofii, dovleceii și fasolea verde.', '2026-10-12T03:00:00.000Z', '2026-10-12T03:00:00.000Z'),
  ('ciorba-de-legume:s2', 'ciorba-de-legume', 1, 'Încălzește uleiul într-o oală și călește ceapa, morcovii, păstârnacul și țelina 5 minute, amestecând.', '2026-10-12T03:00:00.000Z', '2026-10-12T03:00:00.000Z'),
  ('ciorba-de-legume:s3', 'ciorba-de-legume', 2, 'Adaugă 2,5 l de apă caldă, ardeiul, cartofii și fasolea verde. Fierbe la foc mediu 15 minute.', '2026-10-12T03:00:00.000Z', '2026-10-12T03:00:00.000Z'),
  ('ciorba-de-legume:s4', 'ciorba-de-legume', 3, 'Pune dovleceii și roșiile tăiate cubulețe și mai fierbe 10 minute.', '2026-10-12T03:00:00.000Z', '2026-10-12T03:00:00.000Z'),
  ('ciorba-de-legume:s5', 'ciorba-de-legume', 4, 'Toarnă borșul, sare și piper după gust și lasă să dea în clocot 5 minute.', '2026-10-12T03:00:00.000Z', '2026-10-12T03:00:00.000Z'),
  ('ciorba-de-legume:s6', 'ciorba-de-legume', 5, 'Stinge focul, adaugă leușteanul și pătrunjelul tocate și servește cu smântână, dacă vrei.', '2026-10-12T03:00:00.000Z', '2026-10-12T03:00:00.000Z'),
  ('ciorba-de-pui:s1', 'ciorba-de-pui', 0, 'Pune pulpele de pui în oală cu 2,5 l de apă rece și sare. Fierbe la foc mic 30 de minute, spumând din când în când.', '2026-10-12T03:00:00.000Z', '2026-10-12T03:00:00.000Z'),
  ('ciorba-de-pui:s2', 'ciorba-de-pui', 1, 'Adaugă ceapa întreagă, morcovii și țelina tăiate bucăți și mai fierbe 15 minute.', '2026-10-12T03:00:00.000Z', '2026-10-12T03:00:00.000Z'),
  ('ciorba-de-pui:s3', 'ciorba-de-pui', 2, 'Scoate pulpele și legumele. Desprinde carnea de pe os și taie-o bucățele.', '2026-10-12T03:00:00.000Z', '2026-10-12T03:00:00.000Z'),
  ('ciorba-de-pui:s4', 'ciorba-de-pui', 3, 'Pune orezul spălat în supă și fierbe 15 minute, până se înmoaie. Pune carnea înapoi în oală.', '2026-10-12T03:00:00.000Z', '2026-10-12T03:00:00.000Z'),
  ('ciorba-de-pui:s5', 'ciorba-de-pui', 4, 'Bate gălbenușurile cu sucul de lămâie, adaugă 2 polonice de supă fierbinte, amestecând continuu, apoi toarnă totul în oală.', '2026-10-12T03:00:00.000Z', '2026-10-12T03:00:00.000Z'),
  ('ciorba-de-pui:s6', 'ciorba-de-pui', 5, 'Nu mai fierbe supa. Adaugă piper și pătrunjelul tocat și servește imediat.', '2026-10-12T03:00:00.000Z', '2026-10-12T03:00:00.000Z'),
  ('supa-de-pui-cu-taitei:s1', 'supa-de-pui-cu-taitei', 0, 'Pune carnea de pui în oală cu 3 l de apă rece și sare. Adu la fierbere și dă la o parte spuma.', '2026-10-12T03:00:00.000Z', '2026-10-12T03:00:00.000Z'),
  ('supa-de-pui-cu-taitei:s2', 'supa-de-pui-cu-taitei', 1, 'Adaugă ceapa întreagă, morcovii, rădăcina de pătrunjel și țelina. Fierbe la foc mic 50 de minute.', '2026-10-12T03:00:00.000Z', '2026-10-12T03:00:00.000Z'),
  ('supa-de-pui-cu-taitei:s3', 'supa-de-pui-cu-taitei', 2, 'Scoate carnea și legumele. Desprinde carnea de pe os și taie-o bucățele; taie morcovii rondele.', '2026-10-12T03:00:00.000Z', '2026-10-12T03:00:00.000Z'),
  ('supa-de-pui-cu-taitei:s4', 'supa-de-pui-cu-taitei', 3, 'Strecoară supa, pune-o înapoi pe foc și adu-o la fierbere.', '2026-10-12T03:00:00.000Z', '2026-10-12T03:00:00.000Z'),
  ('supa-de-pui-cu-taitei:s5', 'supa-de-pui-cu-taitei', 4, 'Adaugă tăițeii și fierbe 5 minute, sau cât scrie pe pachet.', '2026-10-12T03:00:00.000Z', '2026-10-12T03:00:00.000Z'),
  ('supa-de-pui-cu-taitei:s6', 'supa-de-pui-cu-taitei', 5, 'Pune înapoi carnea și morcovii, potrivește de sare și piper și presară pătrunjel tocat.', '2026-10-12T03:00:00.000Z', '2026-10-12T03:00:00.000Z'),
  ('ciorba-de-fasole-cu-afumatura:s1', 'ciorba-de-fasole-cu-afumatura', 0, 'Scurge fasolea înmuiată, pune-o în oală cu apă rece și fierbe 10 minute. Aruncă apa și acoperă cu 3 l de apă proaspătă.', '2026-10-12T03:00:00.000Z', '2026-10-12T03:00:00.000Z'),
  ('ciorba-de-fasole-cu-afumatura:s2', 'ciorba-de-fasole-cu-afumatura', 1, 'Adaugă costița afumată tăiată bucăți și foile de dafin. Fierbe la foc mic 60 de minute.', '2026-10-12T03:00:00.000Z', '2026-10-12T03:00:00.000Z'),
  ('ciorba-de-fasole-cu-afumatura:s3', 'ciorba-de-fasole-cu-afumatura', 2, 'Între timp, călește ceapa tocată, morcovii rași și țelina cubulețe în ulei, 8 minute. Adaugă bulionul și boiaua și mai ține pe foc 2 minute.', '2026-10-12T03:00:00.000Z', '2026-10-12T03:00:00.000Z'),
  ('ciorba-de-fasole-cu-afumatura:s4', 'ciorba-de-fasole-cu-afumatura', 3, 'Pune prăjeala în oală, adaugă ardeiul tăiat cubulețe și fierbe încă 30 de minute, până fasolea se înmoaie.', '2026-10-12T03:00:00.000Z', '2026-10-12T03:00:00.000Z'),
  ('ciorba-de-fasole-cu-afumatura:s5', 'ciorba-de-fasole-cu-afumatura', 4, 'Toarnă borșul și fierbe 10 minute. Potrivește de sare și piper.', '2026-10-12T03:00:00.000Z', '2026-10-12T03:00:00.000Z'),
  ('ciorba-de-fasole-cu-afumatura:s6', 'ciorba-de-fasole-cu-afumatura', 5, 'Presară leuștean tocat și servește cu ardei iute, dacă îți place.', '2026-10-12T03:00:00.000Z', '2026-10-12T03:00:00.000Z'),
  ('ciorba-de-vacuta:s1', 'ciorba-de-vacuta', 0, 'Pune carnea de vită în oală cu 3 l de apă rece și sare. Adu la fierbere și dă spuma la o parte.', '2026-10-12T03:00:00.000Z', '2026-10-12T03:00:00.000Z'),
  ('ciorba-de-vacuta:s2', 'ciorba-de-vacuta', 1, 'Fierbe la foc mic 60 de minute, apoi adaugă ceapa, morcovii, păstârnacul și țelina tăiate cubulețe.', '2026-10-12T03:00:00.000Z', '2026-10-12T03:00:00.000Z'),
  ('ciorba-de-vacuta:s3', 'ciorba-de-vacuta', 2, 'După 15 minute pune ardeiul și cartofii tăiați cubulețe și fierbe încă 15 minute.', '2026-10-12T03:00:00.000Z', '2026-10-12T03:00:00.000Z'),
  ('ciorba-de-vacuta:s4', 'ciorba-de-vacuta', 3, 'Adaugă bulionul și borșul. Mai fierbe 10 minute, până carnea e fragedă.', '2026-10-12T03:00:00.000Z', '2026-10-12T03:00:00.000Z'),
  ('ciorba-de-vacuta:s5', 'ciorba-de-vacuta', 4, 'Scoate carnea, taie-o în bucăți și pune-o înapoi în oală. Potrivește de sare și piper.', '2026-10-12T03:00:00.000Z', '2026-10-12T03:00:00.000Z'),
  ('ciorba-de-vacuta:s6', 'ciorba-de-vacuta', 5, 'Presară verdeața tocată și servește cu smântână, dacă vrei.', '2026-10-12T03:00:00.000Z', '2026-10-12T03:00:00.000Z'),
  ('ciorba-de-loboda:s1', 'ciorba-de-loboda', 0, 'Spală loboda de mai multe ori și toac-o grosier.', '2026-10-12T03:00:00.000Z', '2026-10-12T03:00:00.000Z'),
  ('ciorba-de-loboda:s2', 'ciorba-de-loboda', 1, 'Încălzește uleiul și călește ceapa tocată și morcovul ras 5 minute.', '2026-10-12T03:00:00.000Z', '2026-10-12T03:00:00.000Z'),
