  ('ciorba-de-loboda:s6', 'ciorba-de-loboda', 5, 'Presară mărar și pătrunjel tocate. Servește cu smântână, dacă îți place.', '2026-10-12T03:00:00.000Z', '2026-10-12T03:00:00.000Z'),
  ('supa-crema-de-dovleac:s1', 'supa-crema-de-dovleac', 0, 'Curăță dovleacul, ceapa, morcovii și cartoful și taie-le cuburi mici.', '2026-10-12T03:00:00.000Z', '2026-10-12T03:00:00.000Z'),
  ('supa-crema-de-dovleac:s2', 'supa-crema-de-dovleac', 1, 'Topește untul într-o oală și călește ceapa și usturoiul 3 minute, fără să se rumenească.', '2026-10-12T03:00:00.000Z', '2026-10-12T03:00:00.000Z'),
