  ('supa-crema-de-dovleac:s4', 'supa-crema-de-dovleac', 3, 'Mixează supa cu un blender vertical până devine fină.', '2026-10-12T03:00:00.000Z', '2026-10-12T03:00:00.000Z'),
  ('supa-crema-de-dovleac:s5', 'supa-crema-de-dovleac', 4, 'Adaugă smântâna, sare, piper și puțină nucșoară și mai încălzește 2 minute, fără să fiarbă tare.', '2026-10-12T03:00:00.000Z', '2026-10-12T03:00:00.000Z'),
  ('supa-crema-de-dovleac:s6', 'supa-crema-de-dovleac', 5, 'Servește cu semințe de dovleac presărate deasupra.', '2026-10-12T03:00:00.000Z', '2026-10-12T03:00:00.000Z'),
  ('supa-crema-de-legume:s1', 'supa-crema-de-legume', 0, 'Taie ceapa, morcovii, cartofii și dovleceii cuburi, iar broccoli buchețele.', '2026-10-12T03:00:00.000Z', '2026-10-12T03:00:00.000Z'),
