  ('supa-crema-de-legume:s3', 'supa-crema-de-legume', 2, 'Adaugă morcovii și cartofii, acoperă cu 1,2 l de apă fierbinte și fierbe 10 minute.', '2026-10-12T03:00:00.000Z', '2026-10-12T03:00:00.000Z'),
  ('supa-crema-de-legume:s4', 'supa-crema-de-legume', 3, 'Pune dovleceii și broccoli și fierbe încă 10 minute, până toate legumele sunt moi.', '2026-10-12T03:00:00.000Z', '2026-10-12T03:00:00.000Z'),
  ('supa-crema-de-legume:s5', 'supa-crema-de-legume', 4, 'Mixează cu blenderul vertical până ai o cremă fină. Adaugă smântana, dacă folosești, sare și piper.', '2026-10-12T03:00:00.000Z', '2026-10-12T03:00:00.000Z'),
  ('supa-crema-de-legume:s6', 'supa-crema-de-legume', 5, 'Mai încălzește 2 minute și servește cu pătrunjel tocat.', '2026-10-12T03:00:00.000Z', '2026-10-12T03:00:00.000Z'),
  ('supa-de-rosii:s1', 'supa-de-rosii', 0, 'Taie roșiile bucăți, iar ceapa, morcovul și usturoiul mărunt.', '2026-10-12T03:00:00.000Z', '2026-10-12T03:00:00.000Z'),
