  ('supa-de-rosii:s5', 'supa-de-rosii', 4, 'Potrivește de sare și piper și mai încălzește 3 minute.', '2026-10-12T03:00:00.000Z', '2026-10-12T03:00:00.000Z'),
  ('supa-de-rosii:s6', 'supa-de-rosii', 5, 'Servește cu busuioc rupt deasupra și puțină smântână.', '2026-10-12T03:00:00.000Z', '2026-10-12T03:00:00.000Z'),
  ('bors-de-peste:s1', 'bors-de-peste', 0, 'Toacă ceapa, morcovii, păstârnacul, țelina și ardeiul. Pune-le într-o oală cu 3 l de apă și sare.', '2026-10-12T03:00:00.000Z', '2026-10-12T03:00:00.000Z'),
  ('bors-de-peste:s2', 'bors-de-peste', 1, 'Fierbe legumele la foc mediu 20 de minute, până se înmoaie.', '2026-10-12T03:00:00.000Z', '2026-10-12T03:00:00.000Z'),
