  ('bors-de-peste:s4', 'bors-de-peste', 3, 'Pune bucățile de pește în oală, cu grijă, și fierbe la foc mic 15–20 de minute, fără să amesteci prea mult.', '2026-10-12T03:00:00.000Z', '2026-10-12T03:00:00.000Z'),
  ('bors-de-peste:s5', 'bors-de-peste', 4, 'Toarnă borșul, dă un clocot și potrivește de sare.', '2026-10-12T03:00:00.000Z', '2026-10-12T03:00:00.000Z'),
  ('bors-de-peste:s6', 'bors-de-peste', 5, 'Stinge focul, presară leuștean și pătrunjel tocate și servește cu ardei iute.', '2026-10-12T03:00:00.000Z', '2026-10-12T03:00:00.000Z'),
  ('supa-de-galuste:s1', 'supa-de-galuste', 0, 'Pune puiul în oală cu 3 l de apă rece și sare. Adu la fierbere, dă spuma la o parte și adaugă ceapa, morcovii, rădăcina de pătrunjel și țelina.', '2026-10-12T03:00:00.000Z', '2026-10-12T03:00:00.000Z'),
  ('supa-de-galuste:s2', 'supa-de-galuste', 1, 'Fierbe la foc mic 50 de minute, apoi scoate carnea și legumele. Strecoară supa.', '2026-10-12T03:00:00.000Z', '2026-10-12T03:00:00.000Z'),
  ('supa-de-galuste:s3', 'supa-de-galuste', 2, 'Bate ouăle cu un praf de sare, adaugă untul topit și grisul și amestecă. Lasă compoziția 10 minute să se umfle.', '2026-10-12T03:00:00.000Z', '2026-10-12T03:00:00.000Z'),
  ('supa-de-galuste:s4', 'supa-de-galuste', 3, 'Adu supa la clocot. Cu două linguri ude, formează găluște și pune-le pe rând în supă.', '2026-10-12T03:00:00.000Z', '2026-10-12T03:00:00.000Z'),
  ('supa-de-galuste:s5', 'supa-de-galuste', 4, 'Fierbe 12–15 minute la foc mic, acoperit, până găluștele plutesc și cresc.', '2026-10-12T03:00:00.000Z', '2026-10-12T03:00:00.000Z'),
  ('supa-de-galuste:s6', 'supa-de-galuste', 5, 'Pune carnea desfăcută și morcovii tăiați rondele în supă, adaugă pătrunjel tocat și piper.', '2026-10-12T03:00:00.000Z', '2026-10-12T03:00:00.000Z'),
  ('ciorba-taraneasca-de-porc:s1', 'ciorba-taraneasca-de-porc', 0, 'Pune carnea de porc în oală cu 3 l de apă rece și sare. Adu la fierbere și dă spuma la o parte.', '2026-10-12T03:00:00.000Z', '2026-10-12T03:00:00.000Z'),
  ('ciorba-taraneasca-de-porc:s2', 'ciorba-taraneasca-de-porc', 1, 'Adaugă ceapa, morcovii, țelina și păstârnacul tăiate cubulețe. Fierbe la foc mic 40 de minute.', '2026-10-12T03:00:00.000Z', '2026-10-12T03:00:00.000Z'),
