  ('ciorba-taraneasca-de-porc:s4', 'ciorba-taraneasca-de-porc', 3, 'Adaugă bulionul și borșul și fierbe încă 10 minute, până carnea e fragedă.', '2026-10-12T03:00:00.000Z', '2026-10-12T03:00:00.000Z'),
  ('ciorba-taraneasca-de-porc:s5', 'ciorba-taraneasca-de-porc', 4, 'Pune usturoiul pisat, sare și piper și dă un clocot.', '2026-10-12T03:00:00.000Z', '2026-10-12T03:00:00.000Z'),
  ('ciorba-taraneasca-de-porc:s6', 'ciorba-taraneasca-de-porc', 5, 'Presară leuștean și pătrunjel tocate și servește cu ardei iute.', '2026-10-12T03:00:00.000Z', '2026-10-12T03:00:00.000Z'),
  ('omleta-cu-legume:s1', 'omleta-cu-legume', 0, 'Taie ardeiul, roșia și ciupercile cubulețe, iar ceapa verde felii subțiri.', '2026-10-12T03:00:00.000Z', '2026-10-12T03:00:00.000Z'),
  ('omleta-cu-legume:s2', 'omleta-cu-legume', 1, 'Încălzește uleiul într-o tigaie și călește ardeiul și ciupercile 3–4 minute.', '2026-10-12T03:00:00.000Z', '2026-10-12T03:00:00.000Z'),
