  ('omleta-cu-legume:s4', 'omleta-cu-legume', 3, 'Bate ouăle cu sare și piper și toarnă-le peste legume.', '2026-10-12T03:00:00.000Z', '2026-10-12T03:00:00.000Z'),
  ('omleta-cu-legume:s5', 'omleta-cu-legume', 4, 'Gătește la foc mic, acoperit, 3–4 minute, până se prinde omleta. Presară cașcavalul, dacă folosești.', '2026-10-12T03:00:00.000Z', '2026-10-12T03:00:00.000Z'),
  ('omleta-cu-legume:s6', 'omleta-cu-legume', 5, 'Îndoaie omleta în două și servește cu pătrunjel tocat.', '2026-10-12T03:00:00.000Z', '2026-10-12T03:00:00.000Z'),
  ('oua-ochiuri:s1', 'oua-ochiuri', 0, 'Prăjește feliile de pâine în toaster sau într-o tigaie uscată, până se rumenesc.', '2026-10-12T03:00:00.000Z', '2026-10-12T03:00:00.000Z'),
  ('oua-ochiuri:s2', 'oua-ochiuri', 1, 'Topește untul într-o tigaie la foc mediu.', '2026-10-12T03:00:00.000Z', '2026-10-12T03:00:00.000Z'),
