  ('salata-de-oua:s1', 'salata-de-oua', 0, 'Pune ouăle în apă clocotită și fierbe-le 10 minute. Răcește-le în apă rece și curăță-le.', '2026-10-12T03:00:00.000Z', '2026-10-12T03:00:00.000Z'),
  ('salata-de-oua:s2', 'salata-de-oua', 1, 'Taie ouăle mărunt cu cuțitul sau cu furculița.', '2026-10-12T03:00:00.000Z', '2026-10-12T03:00:00.000Z'),
  ('salata-de-oua:s3', 'salata-de-oua', 2, 'Toacă ceapa verde și castraveții murați, dacă îi folosești.', '2026-10-12T03:00:00.000Z', '2026-10-12T03:00:00.000Z'),
