  ('terci-de-ovaz-cu-fructe:s1', 'terci-de-ovaz-cu-fructe', 0, 'Pune fulgii de ovăz și laptele într-o oală mică.', '2026-10-12T03:00:00.000Z', '2026-10-12T03:00:00.000Z'),
  ('terci-de-ovaz-cu-fructe:s2', 'terci-de-ovaz-cu-fructe', 1, 'Încălzește la foc mic 6–8 minute, amestecând des, până se îngroașă.', '2026-10-12T03:00:00.000Z', '2026-10-12T03:00:00.000Z'),
