  ('terci-de-ovaz-cu-fructe:s4', 'terci-de-ovaz-cu-fructe', 3, 'Împarte terciul în două boluri și pune fructele deasupra.', '2026-10-12T03:00:00.000Z', '2026-10-12T03:00:00.000Z'),
  ('terci-de-ovaz-cu-fructe:s5', 'terci-de-ovaz-cu-fructe', 4, 'Adaugă mierea, puțină scorțișoară și nucile sparte, dacă vrei.', '2026-10-12T03:00:00.000Z', '2026-10-12T03:00:00.000Z'),
  ('clatite:s1', 'clatite', 0, 'Bate ouăle cu zahărul și un praf de sare. Adaugă jumătate din lapte.', '2026-10-12T03:00:00.000Z', '2026-10-12T03:00:00.000Z'),
  ('clatite:s2', 'clatite', 1, 'Încorporează făina treptat, amestecând ca să nu rămână cocoloașe. Adaugă restul laptelui și o lingură de ulei.', '2026-10-12T03:00:00.000Z', '2026-10-12T03:00:00.000Z'),
  ('clatite:s3', 'clatite', 2, 'Lasă aluatul 15 minute să se odihnească.', '2026-10-12T03:00:00.000Z', '2026-10-12T03:00:00.000Z'),
  ('clatite:s4', 'clatite', 3, 'Încinge o tigaie unsă ușor cu ulei. Toarnă un polonic mic de aluat și întinde-l în strat subțire.', '2026-10-12T03:00:00.000Z', '2026-10-12T03:00:00.000Z'),
  ('clatite:s5', 'clatite', 4, 'Coace 1–2 minute pe o parte, până se rumenește, apoi întoarce clătita și mai coace 1 minut.', '2026-10-12T03:00:00.000Z', '2026-10-12T03:00:00.000Z'),
  ('clatite:s6', 'clatite', 5, 'Umple cu dulceață sau cu ce îți place și rulează clătitele.', '2026-10-12T03:00:00.000Z', '2026-10-12T03:00:00.000Z'),
  ('sandvis-cu-branza-si-legume:s1', 'sandvis-cu-branza-si-legume', 0, 'Prăjește ușor feliile de pâine, dacă vrei să fie crocante.', '2026-10-12T03:00:00.000Z', '2026-10-12T03:00:00.000Z'),
  ('sandvis-cu-branza-si-legume:s2', 'sandvis-cu-branza-si-legume', 1, 'Întinde crema de brânză pe toate feliile.', '2026-10-12T03:00:00.000Z', '2026-10-12T03:00:00.000Z'),
