  ('sandvis-cu-branza-si-legume:s5', 'sandvis-cu-branza-si-legume', 4, 'Acoperă cu celelalte felii, taie sandvișurile în două și servește.', '2026-10-12T03:00:00.000Z', '2026-10-12T03:00:00.000Z'),
  ('bulz:s1', 'bulz', 0, 'Fierbe 1,2 l de apă cu sare. Toarnă malaiul în ploaie, amestecând continuu, și fierbe 25 de minute la foc mic, până se desprinde de oală.', '2026-10-12T03:00:00.000Z', '2026-10-12T03:00:00.000Z'),
  ('bulz:s2', 'bulz', 1, 'Încălzește cuptorul la 200°C.', '2026-10-12T03:00:00.000Z', '2026-10-12T03:00:00.000Z'),
  ('bulz:s3', 'bulz', 2, 'Cu mâinile ude, formează patru bulgări de mămăligă și fă câte o adâncitură în fiecare.', '2026-10-12T03:00:00.000Z', '2026-10-12T03:00:00.000Z'),
  ('bulz:s4', 'bulz', 3, 'Umple adânciturile cu brânză de burduf și telemea sfărâmată și închide bulgării.', '2026-10-12T03:00:00.000Z', '2026-10-12T03:00:00.000Z'),
  ('bulz:s5', 'bulz', 4, 'Pune-i pe o tavă unsă cu unt și coace 15 minute, până se rumenesc și brânza se topește.', '2026-10-12T03:00:00.000Z', '2026-10-12T03:00:00.000Z'),
  ('bulz:s6', 'bulz', 5, 'Servește fierbinte, cu smântână.', '2026-10-12T03:00:00.000Z', '2026-10-12T03:00:00.000Z'),
  ('gris-cu-lapte:s1', 'gris-cu-lapte', 0, 'Pune laptele cu zahărul la încălzit într-o oală mică, la foc mediu.', '2026-10-12T03:00:00.000Z', '2026-10-12T03:00:00.000Z'),
  ('gris-cu-lapte:s2', 'gris-cu-lapte', 1, 'Când laptele începe să fiarbă, adaugă grisul în ploaie, amestecând continuu cu un tel.', '2026-10-12T03:00:00.000Z', '2026-10-12T03:00:00.000Z'),
  ('gris-cu-lapte:s3', 'gris-cu-lapte', 2, 'Fierbe la foc mic 4–5 minute, mereu amestecând, până se îngroașă.', '2026-10-12T03:00:00.000Z', '2026-10-12T03:00:00.000Z'),
  ('gris-cu-lapte:s4', 'gris-cu-lapte', 3, 'Adaugă untul, dacă îl folosești, și stinge focul.', '2026-10-12T03:00:00.000Z', '2026-10-12T03:00:00.000Z'),
  ('gris-cu-lapte:s5', 'gris-cu-lapte', 4, 'Servește cald, cu scorțișoară sau dulceață deasupra.', '2026-10-12T03:00:00.000Z', '2026-10-12T03:00:00.000Z'),
  ('iaurt-cu-musli-si-fructe:s1', 'iaurt-cu-musli-si-fructe', 0, 'Taie banana rondele și mărul cubulețe.', '2026-10-12T03:00:00.000Z', '2026-10-12T03:00:00.000Z'),
  ('iaurt-cu-musli-si-fructe:s2', 'iaurt-cu-musli-si-fructe', 1, 'Pune iaurtul în două boluri.', '2026-10-12T03:00:00.000Z', '2026-10-12T03:00:00.000Z'),
  ('iaurt-cu-musli-si-fructe:s3', 'iaurt-cu-musli-si-fructe', 2, 'Adaugă fructele deasupra.', '2026-10-12T03:00:00.000Z', '2026-10-12T03:00:00.000Z'),
  ('iaurt-cu-musli-si-fructe:s4', 'iaurt-cu-musli-si-fructe', 3, 'Presară muslile chiar înainte de servire, ca să rămână crocante.', '2026-10-12T03:00:00.000Z', '2026-10-12T03:00:00.000Z'),
  ('iaurt-cu-musli-si-fructe:s5', 'iaurt-cu-musli-si-fructe', 4, 'Dacă vrei mai dulce, adaugă puțină miere.', '2026-10-12T03:00:00.000Z', '2026-10-12T03:00:00.000Z'),
  ('ochiuri-romanesti-scrob:s1', 'ochiuri-romanesti-scrob', 0, 'Spală și toacă ceapa verde, cu tot cu părțile verzi.', '2026-10-12T03:00:00.000Z', '2026-10-12T03:00:00.000Z'),
  ('ochiuri-romanesti-scrob:s2', 'ochiuri-romanesti-scrob', 1, 'Topește untul într-o tigaie și călește ceapa 2–3 minute, la foc mic.', '2026-10-12T03:00:00.000Z', '2026-10-12T03:00:00.000Z'),
  ('ochiuri-romanesti-scrob:s3', 'ochiuri-romanesti-scrob', 2, 'Bate ouăle cu sare și piper și toarnă-le peste ceapă.', '2026-10-12T03:00:00.000Z', '2026-10-12T03:00:00.000Z'),
  ('ochiuri-romanesti-scrob:s4', 'ochiuri-romanesti-scrob', 3, 'Amestecă încet, 2–3 minute, până se închag, dar rămân moi și cremoase.', '2026-10-12T03:00:00.000Z', '2026-10-12T03:00:00.000Z'),
  ('ochiuri-romanesti-scrob:s5', 'ochiuri-romanesti-scrob', 4, 'Presară telemeaua, dacă folosești, și servește imediat cu pâine.', '2026-10-12T03:00:00.000Z', '2026-10-12T03:00:00.000Z'),
  ('sarmale:s1', 'sarmale', 0, 'Toacă ceapa mărunt și călește-o în ulei 5 minute, cu boiaua la final. Lasă-o să se răcească.', '2026-10-12T03:00:00.000Z', '2026-10-12T03:00:00.000Z'),
  ('sarmale:s2', 'sarmale', 1, 'Amestecă ceapa cu carnea tocată, orezul spălat, jumătate din verdeața tocată, cimbrul, sare și piper.', '2026-10-12T03:00:00.000Z', '2026-10-12T03:00:00.000Z'),
  ('sarmale:s3', 'sarmale', 2, 'Pune pe fiecare foaie de varză câte o lingură de umplutură și rulează strâns, îndoind marginile spre interior.', '2026-10-12T03:00:00.000Z', '2026-10-12T03:00:00.000Z'),
  ('sarmale:s4', 'sarmale', 3, 'Așază în oală varza tocată, apoi sarmalele în straturi, cu dafinul și restul verdeței între ele.', '2026-10-12T03:00:00.000Z', '2026-10-12T03:00:00.000Z'),
  ('sarmale:s5', 'sarmale', 4, 'Amestecă bulionul cu 500 ml de apă, toarnă peste sarmale până le acoperă și pune deasupra câteva foi de varză.', '2026-10-12T03:00:00.000Z', '2026-10-12T03:00:00.000Z'),
  ('sarmale:s6', 'sarmale', 5, 'Fierbe la foc mic, cu capacul pus, 2 ore, până se înmoaie varza și orezul.', '2026-10-12T03:00:00.000Z', '2026-10-12T03:00:00.000Z'),
  ('sarmale:s7', 'sarmale', 6, 'Lasă-le 15 minute în oală după ce stingi focul. Servește cu smântână, dacă vrei.', '2026-10-12T03:00:00.000Z', '2026-10-12T03:00:00.000Z'),
  ('ardei-umpluti:s1', 'ardei-umpluti', 0, 'Spală ardeii, taie-le capacele și scoate cotoarele și semințele. Păstrează capacele.', '2026-10-12T03:00:00.000Z', '2026-10-12T03:00:00.000Z'),
  ('ardei-umpluti:s2', 'ardei-umpluti', 1, 'Călește o ceapă tocată și morcovul ras în 30 ml de ulei, 5 minute.', '2026-10-12T03:00:00.000Z', '2026-10-12T03:00:00.000Z'),
  ('ardei-umpluti:s3', 'ardei-umpluti', 2, 'Amestecă legumele răcite cu carnea, orezul spălat, jumătate din verdeață, sare și piper.', '2026-10-12T03:00:00.000Z', '2026-10-12T03:00:00.000Z'),
  ('ardei-umpluti:s4', 'ardei-umpluti', 3, 'Umple ardeii cu compoziția, fără să îi îndesești prea tare, și pune-le capacele.', '2026-10-12T03:00:00.000Z', '2026-10-12T03:00:00.000Z'),
  ('ardei-umpluti:s5', 'ardei-umpluti', 4, 'Așază ardeii în oală, adaugă dafinul și ceapa rămasă tăiată felii, apoi toarnă bulionul diluat cu 500 ml de apă.', '2026-10-12T03:00:00.000Z', '2026-10-12T03:00:00.000Z'),
  ('ardei-umpluti:s6', 'ardei-umpluti', 5, 'Fierbe la foc mic, cu capacul pus, 60 de minute, până se înmoaie ardeii și orezul.', '2026-10-12T03:00:00.000Z', '2026-10-12T03:00:00.000Z'),
  ('ardei-umpluti:s7', 'ardei-umpluti', 6, 'Presară verdeața rămasă și servește cu smântână.', '2026-10-12T03:00:00.000Z', '2026-10-12T03:00:00.000Z'),
  ('tocanita-de-porc:s1', 'tocanita-de-porc', 0, 'Încinge uleiul într-o oală cu fundul gros și rumenește carnea 10 minute, pe porții, la foc potrivit.', '2026-10-12T03:00:00.000Z', '2026-10-12T03:00:00.000Z'),
  ('tocanita-de-porc:s2', 'tocanita-de-porc', 1, 'Adaugă ceapa tăiată mărunt și călește 5 minute, până devine sticloasă.', '2026-10-12T03:00:00.000Z', '2026-10-12T03:00:00.000Z'),
  ('tocanita-de-porc:s3', 'tocanita-de-porc', 2, 'Pune pasta de tomate, boiaua, dafinul, cimbrul, sare și piper. Amestecă 1 minut.', '2026-10-12T03:00:00.000Z', '2026-10-12T03:00:00.000Z'),
  ('tocanita-de-porc:s4', 'tocanita-de-porc', 3, 'Toarnă 300 ml de apă caldă, acoperă și fierbe la foc mic 60–70 de minute, amestecând din când în când.', '2026-10-12T03:00:00.000Z', '2026-10-12T03:00:00.000Z'),
  ('tocanita-de-porc:s5', 'tocanita-de-porc', 4, 'Adaugă usturoiul pisat și mai lasă 10 minute, până se leagă sosul.', '2026-10-12T03:00:00.000Z', '2026-10-12T03:00:00.000Z'),
  ('tocanita-de-porc:s6', 'tocanita-de-porc', 5, 'Presară pătrunjel tocat și servește fierbinte, cu mămăligă.', '2026-10-12T03:00:00.000Z', '2026-10-12T03:00:00.000Z'),
  ('ostropel-de-pui:s1', 'ostropel-de-pui', 0, 'Condimentează bucățile de pui cu sare și piper și rumenește-le în ulei încins, 4–5 minute pe fiecare parte.', '2026-10-12T03:00:00.000Z', '2026-10-12T03:00:00.000Z'),
  ('ostropel-de-pui:s2', 'ostropel-de-pui', 1, 'Scoate puiul și, în aceeași oală, călește ceapa tăiată mărunt 5 minute, apoi adaugă boiaua.', '2026-10-12T03:00:00.000Z', '2026-10-12T03:00:00.000Z'),
  ('ostropel-de-pui:s3', 'ostropel-de-pui', 2, 'Pune la loc puiul, adaugă bulionul, dafinul și 200 ml de apă.', '2026-10-12T03:00:00.000Z', '2026-10-12T03:00:00.000Z'),
  ('ostropel-de-pui:s4', 'ostropel-de-pui', 3, 'Acoperă și fierbe la foc mic 35–40 de minute, până se desprinde carnea de pe os.', '2026-10-12T03:00:00.000Z', '2026-10-12T03:00:00.000Z'),
  ('ostropel-de-pui:s5', 'ostropel-de-pui', 4, 'Adaugă usturoiul pisat și mai fierbe 5 minute, fără capac, ca sosul să se îngroașe.', '2026-10-12T03:00:00.000Z', '2026-10-12T03:00:00.000Z'),
  ('ostropel-de-pui:s6', 'ostropel-de-pui', 5, 'Presară pătrunjel tocat și servește cu mămăligă.', '2026-10-12T03:00:00.000Z', '2026-10-12T03:00:00.000Z'),
  ('pilaf-de-pui:s1', 'pilaf-de-pui', 0, 'Rumenește puiul în ulei 6–7 minute, cu sare și piper, apoi scoate-l din oală.', '2026-10-12T03:00:00.000Z', '2026-10-12T03:00:00.000Z'),
  ('pilaf-de-pui:s2', 'pilaf-de-pui', 1, 'În același ulei călește ceapa tocată, morcovul ras și ardeiul tăiat cubulețe, 5 minute.', '2026-10-12T03:00:00.000Z', '2026-10-12T03:00:00.000Z'),
  ('pilaf-de-pui:s3', 'pilaf-de-pui', 2, 'Adaugă orezul spălat și amestecă 2 minute, până devine ușor sticlos.', '2026-10-12T03:00:00.000Z', '2026-10-12T03:00:00.000Z'),
  ('pilaf-de-pui:s4', 'pilaf-de-pui', 3, 'Pune boiaua și puiul la loc, apoi toarnă 600 ml de apă fierbinte în care ai dizolvat cubul de supă.', '2026-10-12T03:00:00.000Z', '2026-10-12T03:00:00.000Z'),
  ('pilaf-de-pui:s5', 'pilaf-de-pui', 4, 'Acoperă și fierbe la foc mic 18–20 de minute, fără să amesteci, până se absoarbe tot lichidul.', '2026-10-12T03:00:00.000Z', '2026-10-12T03:00:00.000Z'),
  ('pilaf-de-pui:s6', 'pilaf-de-pui', 5, 'Lasă 5 minute acoperit, afânează cu furculița și presară pătrunjel tocat.', '2026-10-12T03:00:00.000Z', '2026-10-12T03:00:00.000Z'),
  ('mancare-de-fasole-cu-carnati:s1', 'mancare-de-fasole-cu-carnati', 0, 'Scurge fasolea înmuiată, pune-o la fiert în apă rece și lasă-o 10 minute. Aruncă apa și acoperă din nou cu apă fierbinte.', '2026-10-12T03:00:00.000Z', '2026-10-12T03:00:00.000Z'),
  ('mancare-de-fasole-cu-carnati:s2', 'mancare-de-fasole-cu-carnati', 1, 'Fierbe fasolea la foc mic cu morcovul întreg și dafinul, 60–75 de minute, până se înmoaie. Sărează abia spre final.', '2026-10-12T03:00:00.000Z', '2026-10-12T03:00:00.000Z'),
  ('mancare-de-fasole-cu-carnati:s3', 'mancare-de-fasole-cu-carnati', 2, 'Într-o tigaie, călește ceapa tocată în ulei 5 minute, apoi adaugă cârnații și rumenește-i 5 minute.', '2026-10-12T03:00:00.000Z', '2026-10-12T03:00:00.000Z'),
  ('mancare-de-fasole-cu-carnati:s4', 'mancare-de-fasole-cu-carnati', 3, 'Pune în tigaie pasta de tomate, boiaua și cimbrul, amestecă 1 minut și toarnă totul peste fasole.', '2026-10-12T03:00:00.000Z', '2026-10-12T03:00:00.000Z'),
  ('mancare-de-fasole-cu-carnati:s5', 'mancare-de-fasole-cu-carnati', 4, 'Fierbe împreună 25–30 de minute, până se leagă sosul. Adaugă usturoiul pisat și piper.', '2026-10-12T03:00:00.000Z', '2026-10-12T03:00:00.000Z'),
  ('mancare-de-fasole-cu-carnati:s6', 'mancare-de-fasole-cu-carnati', 5, 'Presară pătrunjel tocat și servește cu murături.', '2026-10-12T03:00:00.000Z', '2026-10-12T03:00:00.000Z'),
  ('ghiveci-de-legume:s1', 'ghiveci-de-legume', 0, 'Încălzește cuptorul la 190 °C.', '2026-10-12T03:00:00.000Z', '2026-10-12T03:00:00.000Z'),
  ('ghiveci-de-legume:s2', 'ghiveci-de-legume', 1, 'Curăță legumele și taie-le cuburi de aproximativ 3 cm. Pune vinetele la scurs cu puțină sare 10 minute, apoi clătește-le.', '2026-10-12T03:00:00.000Z', '2026-10-12T03:00:00.000Z'),
  ('ghiveci-de-legume:s3', 'ghiveci-de-legume', 2, 'Amestecă toate legumele într-o tavă adâncă cu uleiul, sare și piper.', '2026-10-12T03:00:00.000Z', '2026-10-12T03:00:00.000Z'),
  ('ghiveci-de-legume:s4', 'ghiveci-de-legume', 3, 'Dizolvă bulionul în 200 ml de apă și toarnă peste legume. Adaugă usturoiul tăiat felii.', '2026-10-12T03:00:00.000Z', '2026-10-12T03:00:00.000Z'),
  ('ghiveci-de-legume:s5', 'ghiveci-de-legume', 4, 'Acoperă tava cu folie și coace 45 de minute. Scoate folia și mai coace 30 de minute, amestecând o dată.', '2026-10-12T03:00:00.000Z', '2026-10-12T03:00:00.000Z'),
  ('ghiveci-de-legume:s6', 'ghiveci-de-legume', 5, 'Presară pătrunjel tocat și servește cald sau rece.', '2026-10-12T03:00:00.000Z', '2026-10-12T03:00:00.000Z'),
  ('chiftele-de-porc-vita:s1', 'chiftele-de-porc-vita', 0, 'Înmoaie feliile de pâine în lapte 5 minute, apoi stoarce-le bine.', '2026-10-12T03:00:00.000Z', '2026-10-12T03:00:00.000Z'),
  ('chiftele-de-porc-vita:s2', 'chiftele-de-porc-vita', 1, 'Amestecă într-un bol carnea, pâinea, ceapa rasă, usturoiul pisat, oul, pătrunjelul tocat, sare și piper, până se leagă compoziția.', '2026-10-12T03:00:00.000Z', '2026-10-12T03:00:00.000Z'),
  ('chiftele-de-porc-vita:s3', 'chiftele-de-porc-vita', 2, 'Lasă amestecul 15 minute la rece, apoi formează bile turtite cât palma ta de mică.', '2026-10-12T03:00:00.000Z', '2026-10-12T03:00:00.000Z'),
  ('chiftele-de-porc-vita:s4', 'chiftele-de-porc-vita', 3, 'Tăvălește chiftelele prin făină.', '2026-10-12T03:00:00.000Z', '2026-10-12T03:00:00.000Z'),
  ('chiftele-de-porc-vita:s5', 'chiftele-de-porc-vita', 4, 'Prăjește-le în ulei încins la foc mediu, 4–5 minute pe fiecare parte, până se rumenesc și sunt coapte pe dinăuntru.', '2026-10-12T03:00:00.000Z', '2026-10-12T03:00:00.000Z'),
  ('chiftele-de-porc-vita:s6', 'chiftele-de-porc-vita', 5, 'Scurge-le pe hârtie de bucătărie și servește calde.', '2026-10-12T03:00:00.000Z', '2026-10-12T03:00:00.000Z'),
  ('mamaliga-cu-branza-si-smantana:s1', 'mamaliga-cu-branza-si-smantana', 0, 'Fierbe 1,2 l de apă cu puțină sare într-o oală cu fundul gros.', '2026-10-12T03:00:00.000Z', '2026-10-12T03:00:00.000Z'),
  ('mamaliga-cu-branza-si-smantana:s2', 'mamaliga-cu-branza-si-smantana', 1, 'Toarnă mălaiul în ploaie, amestecând continuu cu un tel sau cu lingura de lemn, ca să nu se facă cocoloașe.', '2026-10-12T03:00:00.000Z', '2026-10-12T03:00:00.000Z'),
  ('mamaliga-cu-branza-si-smantana:s3', 'mamaliga-cu-branza-si-smantana', 2, 'Fierbe la foc mic 20–25 de minute, amestecând des, până se desprinde de pe pereții oalei.', '2026-10-12T03:00:00.000Z', '2026-10-12T03:00:00.000Z'),
  ('mamaliga-cu-branza-si-smantana:s4', 'mamaliga-cu-branza-si-smantana', 3, 'Adaugă untul, dacă folosești, și amestecă încă 1 minut.', '2026-10-12T03:00:00.000Z', '2026-10-12T03:00:00.000Z'),
  ('mamaliga-cu-branza-si-smantana:s5', 'mamaliga-cu-branza-si-smantana', 4, 'Răstoarnă mămăliga pe un fund de lemn sau în farfurii și taie-o felii.', '2026-10-12T03:00:00.000Z', '2026-10-12T03:00:00.000Z'),
  ('mamaliga-cu-branza-si-smantana:s6', 'mamaliga-cu-branza-si-smantana', 5, 'Servește caldă, cu brânză și smântână deasupra.', '2026-10-12T03:00:00.000Z', '2026-10-12T03:00:00.000Z'),
  ('tochitura-moldoveneasca:s1', 'tochitura-moldoveneasca', 0, 'Rumenește carnea de porc în ulei 10 minute, la foc mare, amestecând des.', '2026-10-12T03:00:00.000Z', '2026-10-12T03:00:00.000Z'),
  ('tochitura-moldoveneasca:s2', 'tochitura-moldoveneasca', 1, 'Adaugă ceapa tăiată mărunt și cârnații și călește încă 8 minute.', '2026-10-12T03:00:00.000Z', '2026-10-12T03:00:00.000Z'),
  ('tochitura-moldoveneasca:s3', 'tochitura-moldoveneasca', 2, 'Pune pasta de tomate, dafinul, sare și piper, apoi toarnă vinul și lasă-l să scadă 2 minute.', '2026-10-12T03:00:00.000Z', '2026-10-12T03:00:00.000Z'),
  ('tochitura-moldoveneasca:s4', 'tochitura-moldoveneasca', 3, 'Adaugă 200 ml de apă, acoperă și fierbe la foc mic 35–40 de minute, până se înmoaie carnea.', '2026-10-12T03:00:00.000Z', '2026-10-12T03:00:00.000Z'),
  ('tochitura-moldoveneasca:s5', 'tochitura-moldoveneasca', 4, 'Pune usturoiul pisat în ultimele 5 minute. Între timp, fă mămăliga și prăjește ouăle ochiuri.', '2026-10-12T03:00:00.000Z', '2026-10-12T03:00:00.000Z'),
  ('tochitura-moldoveneasca:s6', 'tochitura-moldoveneasca', 5, 'Servește tochitura peste mămăligă, cu ou ochi deasupra și cu brânză, dacă vrei.', '2026-10-12T03:00:00.000Z', '2026-10-12T03:00:00.000Z'),
  ('varza-calita-cu-carne:s1', 'varza-calita-cu-carne', 0, 'Rumenește carnea în jumătate din ulei, 10 minute, apoi adaugă ceapa tocată și călește 5 minute.', '2026-10-12T03:00:00.000Z', '2026-10-12T03:00:00.000Z'),
  ('varza-calita-cu-carne:s2', 'varza-calita-cu-carne', 1, 'Toarnă 150 ml de apă, acoperă și fierbe 25 de minute la foc mic.', '2026-10-12T03:00:00.000Z', '2026-10-12T03:00:00.000Z'),
  ('varza-calita-cu-carne:s3', 'varza-calita-cu-carne', 2, 'Între timp, în altă oală, călește varza în uleiul rămas 10 minute, cu sare, amestecând des.', '2026-10-12T03:00:00.000Z', '2026-10-12T03:00:00.000Z'),
  ('varza-calita-cu-carne:s4', 'varza-calita-cu-carne', 3, 'Adaugă peste varză carnea cu sosul ei, pasta de tomate, boiaua, dafinul, chimenul și piperul.', '2026-10-12T03:00:00.000Z', '2026-10-12T03:00:00.000Z'),
  ('varza-calita-cu-carne:s5', 'varza-calita-cu-carne', 4, 'Acoperă și fierbe la foc mic 25–30 de minute, până se înmoaie varza. Dacă se usucă, adaugă puțină apă caldă.', '2026-10-12T03:00:00.000Z', '2026-10-12T03:00:00.000Z'),
  ('varza-calita-cu-carne:s6', 'varza-calita-cu-carne', 5, 'Presară mărar tocat, dacă folosești, și servește caldă.', '2026-10-12T03:00:00.000Z', '2026-10-12T03:00:00.000Z'),
  ('musaca-de-cartofi:s1', 'musaca-de-cartofi', 0, 'Încălzește cuptorul la 200 °C. Curăță cartofii și taie-i rondele subțiri. Fierbe-i 5 minute în apă cu sare și scurge-i.', '2026-10-12T03:00:00.000Z', '2026-10-12T03:00:00.000Z'),
  ('musaca-de-cartofi:s2', 'musaca-de-cartofi', 1, 'Călește ceapa tocată în ulei 5 minute, apoi adaugă carnea și gătește 12 minute, mărunțind-o cu lingura.', '2026-10-12T03:00:00.000Z', '2026-10-12T03:00:00.000Z'),
  ('musaca-de-cartofi:s3', 'musaca-de-cartofi', 2, 'Adaugă pasta de tomate, pătrunjelul tocat, sare și piper și mai gătește 3 minute.', '2026-10-12T03:00:00.000Z', '2026-10-12T03:00:00.000Z'),
  ('musaca-de-cartofi:s4', 'musaca-de-cartofi', 3, 'Unge o tavă cu ulei. Pune jumătate din cartofi, apoi carnea, apoi restul de cartofi.', '2026-10-12T03:00:00.000Z', '2026-10-12T03:00:00.000Z'),
  ('musaca-de-cartofi:s5', 'musaca-de-cartofi', 4, 'Bate ouăle cu smântâna și puțină sare și toarnă peste musaca.', '2026-10-12T03:00:00.000Z', '2026-10-12T03:00:00.000Z'),
  ('musaca-de-cartofi:s6', 'musaca-de-cartofi', 5, 'Coace 35–40 de minute, până se rumenește deasupra. Lasă 10 minute să se odihnească înainte de tăiat.', '2026-10-12T03:00:00.000Z', '2026-10-12T03:00:00.000Z'),
  ('friptura-de-porc-la-tava:s1', 'friptura-de-porc-la-tava', 0, 'Încălzește cuptorul la 200 °C.', '2026-10-12T03:00:00.000Z', '2026-10-12T03:00:00.000Z'),
  ('friptura-de-porc-la-tava:s2', 'friptura-de-porc-la-tava', 1, 'Freacă carnea cu sare, piper, boia, cimbru și jumătate din usturoiul pisat. Las-o 20 de minute la temperatura camerei.', '2026-10-12T03:00:00.000Z', '2026-10-12T03:00:00.000Z'),
  ('friptura-de-porc-la-tava:s3', 'friptura-de-porc-la-tava', 2, 'Pune carnea într-o tavă, cu ceapa tăiată felii groase, dafinul și uleiul. Toarnă 200 ml de apă pe fundul tăvii.', '2026-10-12T03:00:00.000Z', '2026-10-12T03:00:00.000Z'),
  ('friptura-de-porc-la-tava:s4', 'friptura-de-porc-la-tava', 3, 'Coace 30 de minute la 200 °C, apoi acoperă cu folie și coboară la 170 °C. Mai coace 60 de minute.', '2026-10-12T03:00:00.000Z', '2026-10-12T03:00:00.000Z'),
  ('friptura-de-porc-la-tava:s5', 'friptura-de-porc-la-tava', 4, 'Adaugă cartofii curățați, tăiați felii groase, cu sare și restul de usturoi. Coace încă 30 de minute fără folie, până se rumenesc.', '2026-10-12T03:00:00.000Z', '2026-10-12T03:00:00.000Z'),
  ('friptura-de-porc-la-tava:s6', 'friptura-de-porc-la-tava', 5, 'Lasă carnea 10 minute să se odihnească, apoi taie-o felii și servește cu cartofii și sosul din tavă.', '2026-10-12T03:00:00.000Z', '2026-10-12T03:00:00.000Z'),
  ('pui-la-cuptor-cu-cartofi:s1', 'pui-la-cuptor-cu-cartofi', 0, 'Încălzește cuptorul la 200 °C.', '2026-10-12T03:00:00.000Z', '2026-10-12T03:00:00.000Z'),
  ('pui-la-cuptor-cu-cartofi:s2', 'pui-la-cuptor-cu-cartofi', 1, 'Amestecă într-un castron uleiul, boiaua, cimbrul, usturoiul pisat, sare și piper. Unge pulpele cu amestecul.', '2026-10-12T03:00:00.000Z', '2026-10-12T03:00:00.000Z'),
  ('pui-la-cuptor-cu-cartofi:s3', 'pui-la-cuptor-cu-cartofi', 2, 'Curăță cartofii și taie-i felii groase. Taie ceapa felii și amestec-o cu cartofii, puțin ulei, sare și piper.', '2026-10-12T03:00:00.000Z', '2026-10-12T03:00:00.000Z'),
  ('pui-la-cuptor-cu-cartofi:s4', 'pui-la-cuptor-cu-cartofi', 3, 'Pune cartofii în tavă și așază pulpele deasupra, cu pielea în sus.', '2026-10-12T03:00:00.000Z', '2026-10-12T03:00:00.000Z'),
  ('pui-la-cuptor-cu-cartofi:s5', 'pui-la-cuptor-cu-cartofi', 4, 'Coace 55–60 de minute, întorcând cartofii o dată la jumătate, până se rumenesc pulpele și carnea e gătită pe dinăuntru.', '2026-10-12T03:00:00.000Z', '2026-10-12T03:00:00.000Z'),
  ('pui-la-cuptor-cu-cartofi:s6', 'pui-la-cuptor-cu-cartofi', 5, 'Servește fierbinte, cu murături sau salată.', '2026-10-12T03:00:00.000Z', '2026-10-12T03:00:00.000Z'),
  ('mancare-de-mazare-cu-pui:s1', 'mancare-de-mazare-cu-pui', 0, 'Rumenește puiul în ulei 6–7 minute, cu sare și piper, apoi scoate-l din oală.', '2026-10-12T03:00:00.000Z', '2026-10-12T03:00:00.000Z'),
  ('mancare-de-mazare-cu-pui:s2', 'mancare-de-mazare-cu-pui', 1, 'În același ulei călește ceapa tocată și morcovii tăiați rondele, 5 minute.', '2026-10-12T03:00:00.000Z', '2026-10-12T03:00:00.000Z'),
  ('mancare-de-mazare-cu-pui:s3', 'mancare-de-mazare-cu-pui', 2, 'Adaugă pasta de tomate și puiul la loc, apoi toarnă 300 ml de apă fierbinte. Acoperă și fierbe 15 minute.', '2026-10-12T03:00:00.000Z', '2026-10-12T03:00:00.000Z'),
  ('mancare-de-mazare-cu-pui:s4', 'mancare-de-mazare-cu-pui', 3, 'Adaugă mazărea (nu e nevoie să o dezgheți) și fierbe încă 15–20 de minute la foc mic.', '2026-10-12T03:00:00.000Z', '2026-10-12T03:00:00.000Z'),
  ('mancare-de-mazare-cu-pui:s5', 'mancare-de-mazare-cu-pui', 4, 'Potrivește de sare și piper, apoi stinge focul și presară mărarul și pătrunjelul tocate.', '2026-10-12T03:00:00.000Z', '2026-10-12T03:00:00.000Z'),
  ('tocana-de-cartofi:s1', 'tocana-de-cartofi', 0, 'Curăță cartofii și taie-i cuburi de 2–3 cm.', '2026-10-12T03:00:00.000Z', '2026-10-12T03:00:00.000Z'),
  ('tocana-de-cartofi:s2', 'tocana-de-cartofi', 1, 'Călește ceapa tocată în ulei 5 minute, până devine sticloasă.', '2026-10-12T03:00:00.000Z', '2026-10-12T03:00:00.000Z'),
  ('tocana-de-cartofi:s3', 'tocana-de-cartofi', 2, 'Adaugă pasta de tomate și boiaua și amestecă 1 minut, ca să nu se ardă.', '2026-10-12T03:00:00.000Z', '2026-10-12T03:00:00.000Z'),
  ('tocana-de-cartofi:s4', 'tocana-de-cartofi', 3, 'Pune cartofii, dafinul, sare și piper. Toarnă apă cât să îi acopere pe jumătate.', '2026-10-12T03:00:00.000Z', '2026-10-12T03:00:00.000Z'),
  ('tocana-de-cartofi:s5', 'tocana-de-cartofi', 4, 'Fierbe la foc mic, cu capacul pus, 25 de minute, amestecând de două-trei ori, până se înmoaie cartofii și se îngroașă sosul.', '2026-10-12T03:00:00.000Z', '2026-10-12T03:00:00.000Z'),
  ('tocana-de-cartofi:s6', 'tocana-de-cartofi', 5, 'Adaugă usturoiul pisat, pătrunjelul tocat și servește fierbinte.', '2026-10-12T03:00:00.000Z', '2026-10-12T03:00:00.000Z'),
  ('papricas-de-pui:s1', 'papricas-de-pui', 0, 'Călește ceapa tocată mărunt în ulei, la foc mic, 8 minute, până se înmoaie fără să se rumenească.', '2026-10-12T03:00:00.000Z', '2026-10-12T03:00:00.000Z'),
  ('papricas-de-pui:s2', 'papricas-de-pui', 1, 'Ia oala de pe foc, adaugă boiaua și pasta de tomate și amestecă, apoi pune-o la loc.', '2026-10-12T03:00:00.000Z', '2026-10-12T03:00:00.000Z'),
  ('papricas-de-pui:s3', 'papricas-de-pui', 2, 'Adaugă puiul, ardeiul tăiat cubulețe, sare și piper. Toarnă 200 ml de apă caldă.', '2026-10-12T03:00:00.000Z', '2026-10-12T03:00:00.000Z'),
  ('papricas-de-pui:s4', 'papricas-de-pui', 3, 'Acoperă și fierbe la foc mic 35–40 de minute, până se înmoaie carnea.', '2026-10-12T03:00:00.000Z', '2026-10-12T03:00:00.000Z'),
  ('papricas-de-pui:s5', 'papricas-de-pui', 4, 'Amestecă smântâna cu făina și 3–4 linguri din sosul fierbinte, apoi toarn-o în oală.', '2026-10-12T03:00:00.000Z', '2026-10-12T03:00:00.000Z'),
  ('papricas-de-pui:s6', 'papricas-de-pui', 5, 'Mai fierbe 5 minute, amestecând. Presară pătrunjel, dacă vrei, și servește cu mămăligă.', '2026-10-12T03:00:00.000Z', '2026-10-12T03:00:00.000Z'),
  ('ciulama-de-pui-cu-ciuperci:s1', 'ciulama-de-pui-cu-ciuperci', 0, 'Topește jumătate din unt într-o tigaie și rumenește puiul 6–7 minute, cu sare și piper. Scoate-l.', '2026-10-12T03:00:00.000Z', '2026-10-12T03:00:00.000Z'),
  ('ciulama-de-pui-cu-ciuperci:s2', 'ciulama-de-pui-cu-ciuperci', 1, 'În aceeași tigaie călește ceapa tocată 3 minute, apoi adaugă ciupercile și gătește 8 minute, până se evaporă lichidul.', '2026-10-12T03:00:00.000Z', '2026-10-12T03:00:00.000Z'),
  ('ciulama-de-pui-cu-ciuperci:s3', 'ciulama-de-pui-cu-ciuperci', 2, 'Într-o oală mică, topește untul rămas, adaugă făina și amestecă 1 minut. Toarnă laptele încet, amestecând, până se îngroașă sosul.', '2026-10-12T03:00:00.000Z', '2026-10-12T03:00:00.000Z'),
  ('ciulama-de-pui-cu-ciuperci:s4', 'ciulama-de-pui-cu-ciuperci', 3, 'Pune în sos puiul, ciupercile și usturoiul pisat. Fierbe la foc mic 15 minute.', '2026-10-12T03:00:00.000Z', '2026-10-12T03:00:00.000Z'),
  ('ciulama-de-pui-cu-ciuperci:s5', 'ciulama-de-pui-cu-ciuperci', 4, 'Adaugă smântâna, nucșoara dacă vrei și sare după gust. Mai lasă 2–3 minute, fără să fiarbă tare.', '2026-10-12T03:00:00.000Z', '2026-10-12T03:00:00.000Z'),
  ('ciulama-de-pui-cu-ciuperci:s6', 'ciulama-de-pui-cu-ciuperci', 5, 'Presară pătrunjel tocat și servește cu mămăligă.', '2026-10-12T03:00:00.000Z', '2026-10-12T03:00:00.000Z'),
  ('iahnie-de-fasole:s1', 'iahnie-de-fasole', 0, 'Scurge fasolea înmuiată, acoperă-o cu apă rece și fierbe 10 minute. Aruncă apa și pune apă fierbinte proaspătă.', '2026-10-12T03:00:00.000Z', '2026-10-12T03:00:00.000Z'),
  ('iahnie-de-fasole:s2', 'iahnie-de-fasole', 1, 'Fierbe fasolea la foc mic cu morcovul și dafinul, 60–70 de minute, până se înmoaie.', '2026-10-12T03:00:00.000Z', '2026-10-12T03:00:00.000Z'),
  ('iahnie-de-fasole:s3', 'iahnie-de-fasole', 2, 'Călește ceapa tăiată mărunt în ulei, la foc mic, 15 minute, până se aurește.', '2026-10-12T03:00:00.000Z', '2026-10-12T03:00:00.000Z'),
  ('iahnie-de-fasole:s4', 'iahnie-de-fasole', 3, 'Adaugă pasta de tomate, boiaua și cimbrul și amestecă 1 minut.', '2026-10-12T03:00:00.000Z', '2026-10-12T03:00:00.000Z'),
  ('iahnie-de-fasole:s5', 'iahnie-de-fasole', 4, 'Toarnă ceapa peste fasole, adaugă sare și piper și fierbe împreună 15–20 de minute, până se îngroașă.', '2026-10-12T03:00:00.000Z', '2026-10-12T03:00:00.000Z'),
  ('iahnie-de-fasole:s6', 'iahnie-de-fasole', 5, 'Adaugă usturoiul pisat și pătrunjelul tocat. Servește cu ceapă crudă și murături.', '2026-10-12T03:00:00.000Z', '2026-10-12T03:00:00.000Z'),
  ('mici-la-gratar:s1', 'mici-la-gratar', 0, 'Pune carnea de mici într-un castron. Adaugă usturoiul pisat, bicarbonatul, cimbrul, boiaua, sare și piper.', '2026-10-12T03:00:00.000Z', '2026-10-12T03:00:00.000Z'),
  ('mici-la-gratar:s2', 'mici-la-gratar', 1, 'Frământă 5–7 minute, adăugând 3–4 linguri de apă rece, până compoziția devine lipicioasă.', '2026-10-12T03:00:00.000Z', '2026-10-12T03:00:00.000Z'),
  ('mici-la-gratar:s3', 'mici-la-gratar', 2, 'Acoperă și lasă la rece cel puțin 1 oră, ca să se lege aromele.', '2026-10-12T03:00:00.000Z', '2026-10-12T03:00:00.000Z'),
  ('mici-la-gratar:s4', 'mici-la-gratar', 3, 'Cu mâinile ude, formează rulouri cu lungimea de 8–9 cm.', '2026-10-12T03:00:00.000Z', '2026-10-12T03:00:00.000Z'),
  ('mici-la-gratar:s5', 'mici-la-gratar', 4, 'Încinge grătarul sau o tigaie grill. Coace micii 10–12 minute, întorcându-i des, până se rumenesc uniform.', '2026-10-12T03:00:00.000Z', '2026-10-12T03:00:00.000Z'),
  ('mici-la-gratar:s6', 'mici-la-gratar', 5, 'Servește imediat, cu muștar și pâine proaspătă.', '2026-10-12T03:00:00.000Z', '2026-10-12T03:00:00.000Z'),
  ('drob-de-miel:s1', 'drob-de-miel', 0, 'Fierbe 2 ouă 10 minute, răcește-le și curăță-le de coajă. Fierbe organele în apă cu sare 20 de minute, apoi scurge-le și lasă-le să se răcească.', '2026-10-12T03:00:00.000Z', '2026-10-12T03:00:00.000Z'),
  ('drob-de-miel:s2', 'drob-de-miel', 1, 'Toacă organele fierte mărunt, la satâr sau la mașina de tocat. Încălzește cuptorul la 180 °C.', '2026-10-12T03:00:00.000Z', '2026-10-12T03:00:00.000Z'),
  ('drob-de-miel:s3', 'drob-de-miel', 2, 'Toacă ceapa verde, pătrunjelul și mărarul. Calește ceapa 3 minute în unt.', '2026-10-12T03:00:00.000Z', '2026-10-12T03:00:00.000Z'),
  ('drob-de-miel:s4', 'drob-de-miel', 3, 'Amestecă organele tocate cu verdeața, pâinea stoarsă, cele 5 ouă crude bătute, sare și piper.', '2026-10-12T03:00:00.000Z', '2026-10-12T03:00:00.000Z'),
  ('drob-de-miel:s5', 'drob-de-miel', 4, 'Unge o tavă dreptunghiulară cu unt și pune jumătate din compoziție. Așază cele 2 ouă fierte în lung, apoi acoperă cu restul de compoziție.', '2026-10-12T03:00:00.000Z', '2026-10-12T03:00:00.000Z'),
  ('drob-de-miel:s6', 'drob-de-miel', 5, 'Coace 50–60 de minute, până se rumenește deasupra și e ferm la atingere.', '2026-10-12T03:00:00.000Z', '2026-10-12T03:00:00.000Z'),
  ('drob-de-miel:s7', 'drob-de-miel', 6, 'Lasă drobul să se răcească complet în tavă, apoi taie-l felii.', '2026-10-12T03:00:00.000Z', '2026-10-12T03:00:00.000Z'),
  ('peste-la-cuptor-cu-legume:s1', 'peste-la-cuptor-cu-legume', 0, 'Încălzește cuptorul la 200°C.', '2026-10-12T03:00:00.000Z', '2026-10-12T03:00:00.000Z'),
  ('peste-la-cuptor-cu-legume:s2', 'peste-la-cuptor-cu-legume', 1, 'Taie cartofii rondele subțiri, ceapa felii, ardeiul fâșii și roșiile felii. Amestecă cartofii, ceapa și ardeiul cu jumătate din ulei, sare și piper.', '2026-10-12T03:00:00.000Z', '2026-10-12T03:00:00.000Z'),
  ('peste-la-cuptor-cu-legume:s3', 'peste-la-cuptor-cu-legume', 2, 'Întinde legumele în tavă și coace-le 20 de minute.', '2026-10-12T03:00:00.000Z', '2026-10-12T03:00:00.000Z'),
  ('peste-la-cuptor-cu-legume:s4', 'peste-la-cuptor-cu-legume', 3, 'Condimentează fileurile cu sare, piper, usturoi zdrobit și zeama de la jumătate de lămâie.', '2026-10-12T03:00:00.000Z', '2026-10-12T03:00:00.000Z'),
  ('peste-la-cuptor-cu-legume:s5', 'peste-la-cuptor-cu-legume', 4, 'Așază peștele peste legume, adaugă roșiile și restul de ulei și coace încă 15–20 de minute, până se desface ușor cu furculița.', '2026-10-12T03:00:00.000Z', '2026-10-12T03:00:00.000Z'),
  ('peste-la-cuptor-cu-legume:s6', 'peste-la-cuptor-cu-legume', 5, 'Servește cu pătrunjel tocat și felii de lămâie.', '2026-10-12T03:00:00.000Z', '2026-10-12T03:00:00.000Z'),
  ('saramura-de-crap:s1', 'saramura-de-crap', 0, 'Sărează feliile de crap și lasă-le 20 de minute.', '2026-10-12T03:00:00.000Z', '2026-10-12T03:00:00.000Z'),
  ('saramura-de-crap:s2', 'saramura-de-crap', 1, 'Încălzește uleiul în tigaie și rumenește peștele 6–8 minute pe fiecare parte. Scoate-l pe un platou.', '2026-10-12T03:00:00.000Z', '2026-10-12T03:00:00.000Z'),
  ('saramura-de-crap:s3', 'saramura-de-crap', 2, 'Într-o oală, fierbe 500 ml de apă cu 2 linguri de sare grunjoasă, dafinul, boabele de piper și ardeiul iute 5 minute.', '2026-10-12T03:00:00.000Z', '2026-10-12T03:00:00.000Z'),
  ('saramura-de-crap:s4', 'saramura-de-crap', 3, 'Adaugă usturoiul pisat și boia și mai lasă 2 minute pe foc.', '2026-10-12T03:00:00.000Z', '2026-10-12T03:00:00.000Z'),
  ('saramura-de-crap:s5', 'saramura-de-crap', 4, 'Pune peștele în saramură și lasă-l la foc mic 10 minute, fără să fiarbă tare.', '2026-10-12T03:00:00.000Z', '2026-10-12T03:00:00.000Z'),
  ('saramura-de-crap:s6', 'saramura-de-crap', 5, 'Servește cald, cu mămăligă.', '2026-10-12T03:00:00.000Z', '2026-10-12T03:00:00.000Z'),
  ('pastrav-la-gratar:s1', 'pastrav-la-gratar', 0, 'Spală păstrăvii și șterge-i bine. Freacă-i cu sare și piper, pe dinafară și pe dinăuntru.', '2026-10-12T03:00:00.000Z', '2026-10-12T03:00:00.000Z'),
  ('pastrav-la-gratar:s2', 'pastrav-la-gratar', 1, 'Pune în burta fiecărui pește câteva fire de pătrunjel și o felie de lămâie.', '2026-10-12T03:00:00.000Z', '2026-10-12T03:00:00.000Z'),
  ('pastrav-la-gratar:s3', 'pastrav-la-gratar', 2, 'Unge peștii cu 2 linguri de ulei și lasă-i 10 minute.', '2026-10-12T03:00:00.000Z', '2026-10-12T03:00:00.000Z'),
  ('pastrav-la-gratar:s4', 'pastrav-la-gratar', 3, 'Încinge grătarul și coace peștii 8–10 minute pe fiecare parte, până se desprinde carnea de pe os.', '2026-10-12T03:00:00.000Z', '2026-10-12T03:00:00.000Z'),
  ('pastrav-la-gratar:s5', 'pastrav-la-gratar', 4, 'Pentru mujdei, pisează usturoiul cu sare, adaugă restul de ulei, zeama de la o lămâie și 2 linguri de apă.', '2026-10-12T03:00:00.000Z', '2026-10-12T03:00:00.000Z'),
  ('pastrav-la-gratar:s6', 'pastrav-la-gratar', 5, 'Servește peștele fierbinte, cu mujdeiul deasupra.', '2026-10-12T03:00:00.000Z', '2026-10-12T03:00:00.000Z'),
  ('somon-la-cuptor-cu-lamaie:s1', 'somon-la-cuptor-cu-lamaie', 0, 'Încălzește cuptorul la 200°C.', '2026-10-12T03:00:00.000Z', '2026-10-12T03:00:00.000Z'),
  ('somon-la-cuptor-cu-lamaie:s2', 'somon-la-cuptor-cu-lamaie', 1, 'Taie cartofii noi în jumătăți, amestecă-i cu 2 linguri de ulei, sare și piper și coace-i 10 minute.', '2026-10-12T03:00:00.000Z', '2026-10-12T03:00:00.000Z'),
  ('somon-la-cuptor-cu-lamaie:s3', 'somon-la-cuptor-cu-lamaie', 2, 'Împarte broccoli în buchete. Amestecă-le cu usturoiul tocat și restul de ulei.', '2026-10-12T03:00:00.000Z', '2026-10-12T03:00:00.000Z'),
  ('somon-la-cuptor-cu-lamaie:s4', 'somon-la-cuptor-cu-lamaie', 3, 'Adaugă broccoli în tavă, iar printre legume așază somonul, sărat și piperat.', '2026-10-12T03:00:00.000Z', '2026-10-12T03:00:00.000Z'),
  ('somon-la-cuptor-cu-lamaie:s5', 'somon-la-cuptor-cu-lamaie', 4, 'Stoarce deasupra zeama de lămâie și pune câteva felii de lămâie pe pește.', '2026-10-12T03:00:00.000Z', '2026-10-12T03:00:00.000Z'),
  ('somon-la-cuptor-cu-lamaie:s6', 'somon-la-cuptor-cu-lamaie', 5, 'Coace 12–15 minute, până când somonul se desface ușor. Presară mărar tocat și servește.', '2026-10-12T03:00:00.000Z', '2026-10-12T03:00:00.000Z'),
  ('file-de-cod-cu-piure:s1', 'file-de-cod-cu-piure', 0, 'Curăță cartofii, taie-i bucăți și fierbe-i în apă cu sare 20 de minute, până se înmoaie.', '2026-10-12T03:00:00.000Z', '2026-10-12T03:00:00.000Z'),
  ('file-de-cod-cu-piure:s2', 'file-de-cod-cu-piure', 1, 'Scurge cartofii și zdrobește-i. Adaugă untul și laptele încălzit și amestecă până obții un piure fin. Potrivește de sare.', '2026-10-12T03:00:00.000Z', '2026-10-12T03:00:00.000Z'),
  ('file-de-cod-cu-piure:s3', 'file-de-cod-cu-piure', 2, 'Taie codul în porții, sărează-l, piperează-l și trece-l ușor prin făină.', '2026-10-12T03:00:00.000Z', '2026-10-12T03:00:00.000Z'),
  ('file-de-cod-cu-piure:s4', 'file-de-cod-cu-piure', 3, 'Încinge uleiul într-o tigaie și prăjește peștele 3–4 minute pe fiecare parte, până se rumenește.', '2026-10-12T03:00:00.000Z', '2026-10-12T03:00:00.000Z'),
  ('file-de-cod-cu-piure:s5', 'file-de-cod-cu-piure', 4, 'Servește codul peste piure, cu lămâie și mărar tocat.', '2026-10-12T03:00:00.000Z', '2026-10-12T03:00:00.000Z'),
  ('macrou-la-cuptor:s1', 'macrou-la-cuptor', 0, 'Încălzește cuptorul la 200°C.', '2026-10-12T03:00:00.000Z', '2026-10-12T03:00:00.000Z'),
  ('macrou-la-cuptor:s2', 'macrou-la-cuptor', 1, 'Spală macroul și șterge-l. Fă 3 tăieturi pe fiecare parte și freacă-l cu sare, piper și cimbru.', '2026-10-12T03:00:00.000Z', '2026-10-12T03:00:00.000Z'),
  ('macrou-la-cuptor:s3', 'macrou-la-cuptor', 2, 'Pune în burta peștilor usturoi feliat și felii de lămâie.', '2026-10-12T03:00:00.000Z', '2026-10-12T03:00:00.000Z'),
  ('macrou-la-cuptor:s4', 'macrou-la-cuptor', 3, 'Taie ceapa rondele și roșiile felii și întinde-le în tavă, pe un strat de ulei.', '2026-10-12T03:00:00.000Z', '2026-10-12T03:00:00.000Z'),
  ('macrou-la-cuptor:s5', 'macrou-la-cuptor', 4, 'Așază peștii deasupra, unge-i cu restul de ulei și coace 30–35 de minute, până se rumenesc.', '2026-10-12T03:00:00.000Z', '2026-10-12T03:00:00.000Z'),
  ('macrou-la-cuptor:s6', 'macrou-la-cuptor', 5, 'Servește cu pătrunjel tocat.', '2026-10-12T03:00:00.000Z', '2026-10-12T03:00:00.000Z'),
  ('salata-de-vinete:s1', 'salata-de-vinete', 0, 'Înțeapă vinetele cu o furculiță și coace-le în cuptor la 220°C, 35–40 de minute, întorcându-le o dată, până se înmoaie.', '2026-10-12T03:00:00.000Z', '2026-10-12T03:00:00.000Z'),
  ('salata-de-vinete:s2', 'salata-de-vinete', 1, 'Pune-le într-o strecurătoare, taie-le pe lung și lasă-le 15 minute să-și piardă zeama.', '2026-10-12T03:00:00.000Z', '2026-10-12T03:00:00.000Z'),
  ('salata-de-vinete:s3', 'salata-de-vinete', 2, 'Curăță vinetele de coajă și toacă-le fin cu un cuțit de lemn sau de plastic.', '2026-10-12T03:00:00.000Z', '2026-10-12T03:00:00.000Z'),
  ('salata-de-vinete:s4', 'salata-de-vinete', 3, 'Pune carnea într-un castron și adaugă puțină sare. Toarnă uleiul treptat, amestecând mereu, până devine cremoasă.', '2026-10-12T03:00:00.000Z', '2026-10-12T03:00:00.000Z'),
  ('salata-de-vinete:s5', 'salata-de-vinete', 4, 'Adaugă ceapa tocată mărunt, zeama de lămâie și potrivește de sare.', '2026-10-12T03:00:00.000Z', '2026-10-12T03:00:00.000Z'),
  ('salata-de-vinete:s6', 'salata-de-vinete', 5, 'Servește rece, cu felii de roșii și pâine proaspătă.', '2026-10-12T03:00:00.000Z', '2026-10-12T03:00:00.000Z'),
  ('salata-de-boeuf:s1', 'salata-de-boeuf', 0, 'Fierbe cartofii, morcovii și pătrunjelul cu coaja, 20–25 de minute, până se înmoaie. Lasă-i să se răcească.', '2026-10-12T03:00:00.000Z', '2026-10-12T03:00:00.000Z'),
  ('salata-de-boeuf:s2', 'salata-de-boeuf', 1, 'Fierbe separat pieptul de pui în apă cu sare, 20 de minute. Lasă-l să se răcească în supă.', '2026-10-12T03:00:00.000Z', '2026-10-12T03:00:00.000Z'),
  ('salata-de-boeuf:s3', 'salata-de-boeuf', 2, 'Curăță legumele și taie-le cubulețe. Taie și puiul, și murăturile în cubulețe mici.', '2026-10-12T03:00:00.000Z', '2026-10-12T03:00:00.000Z'),
