  ('salata-de-rosii-cu-castraveti:s1', 'salata-de-rosii-cu-castraveti', 0, 'Spală legumele. Taie roșiile felii sau cuburi mari și castraveții rondele.', '2026-10-12T03:00:00.000Z', '2026-10-12T03:00:00.000Z'),
