  ('salata-de-varza:s1', 'salata-de-varza', 0, 'Scoate frunzele de deasupra și cotorul verzei, apoi taie-o cât mai fin.', '2026-10-12T03:00:00.000Z', '2026-10-12T03:00:00.000Z'),
