  ('salata-de-fasole-verde:s3', 'salata-de-fasole-verde', 2, 'Scurge-o și răcește-o sub apă rece, apoi lasă-o să se scurgă bine.', '2026-10-12T03:00:00.000Z', '2026-10-12T03:00:00.000Z'),
  ('salata-de-fasole-verde:s4', 'salata-de-fasole-verde', 3, 'Pisează usturoiul cu puțină sare și amestecă-l cu uleiul și oțetul.', '2026-10-12T03:00:00.000Z', '2026-10-12T03:00:00.000Z'),
  ('salata-de-fasole-verde:s5', 'salata-de-fasole-verde', 4, 'Toarnă sosul peste fasole, adaugă piper și pătrunjel tocat și amestecă.', '2026-10-12T03:00:00.000Z', '2026-10-12T03:00:00.000Z'),
  ('salata-greceasca:s1', 'salata-greceasca', 0, 'Taie roșiile în felii groase, castraveții în rondele groase și ardeiul în inele.', '2026-10-12T03:00:00.000Z', '2026-10-12T03:00:00.000Z'),
  ('salata-greceasca:s2', 'salata-greceasca', 1, 'Taie ceapa roșie în felii subțiri.', '2026-10-12T03:00:00.000Z', '2026-10-12T03:00:00.000Z'),
  ('salata-greceasca:s3', 'salata-greceasca', 2, 'Pune legumele într-un bol și adaugă măslinele.', '2026-10-12T03:00:00.000Z', '2026-10-12T03:00:00.000Z'),
