  ('salata-greceasca:s5', 'salata-greceasca', 4, 'Pune bucata de feta deasupra și presară oregano. Servește imediat.', '2026-10-12T03:00:00.000Z', '2026-10-12T03:00:00.000Z'),
  ('dovlecei-pane:s1', 'dovlecei-pane', 0, 'Taie dovleceii rondele sau felii de 1 cm. Sărează-i și lasă-i 10 minute, apoi tamponează-i cu un prosop de hârtie.', '2026-10-12T03:00:00.000Z', '2026-10-12T03:00:00.000Z'),
  ('dovlecei-pane:s2', 'dovlecei-pane', 1, 'Pregătește trei farfurii: făina, ouăle bătute cu piper și pesmetul.', '2026-10-12T03:00:00.000Z', '2026-10-12T03:00:00.000Z'),
  ('dovlecei-pane:s3', 'dovlecei-pane', 2, 'Trece fiecare felie prin făină, apoi prin ou și la final prin pesmet.', '2026-10-12T03:00:00.000Z', '2026-10-12T03:00:00.000Z'),
