  ('dovlecei-pane:s5', 'dovlecei-pane', 4, 'Pune-le pe un prosop de hârtie, ca să scape de exces de ulei.', '2026-10-12T03:00:00.000Z', '2026-10-12T03:00:00.000Z'),
  ('dovlecei-pane:s6', 'dovlecei-pane', 5, 'Pentru sos, amestecă iaurtul cu usturoi pisat și puțină sare. Servește feliile calde.', '2026-10-12T03:00:00.000Z', '2026-10-12T03:00:00.000Z'),
  ('chiftele-de-dovlecei:s1', 'chiftele-de-dovlecei', 0, 'Rade dovleceii, sărează-i și lasă-i 10 minute, apoi strânge bine zeama cu mâna.', '2026-10-12T03:00:00.000Z', '2026-10-12T03:00:00.000Z'),
  ('chiftele-de-dovlecei:s2', 'chiftele-de-dovlecei', 1, 'Adaugă ouăle, telemeaua dată pe răzătoare, mărarul tocat și usturoiul pisat.', '2026-10-12T03:00:00.000Z', '2026-10-12T03:00:00.000Z'),
  ('chiftele-de-dovlecei:s3', 'chiftele-de-dovlecei', 2, 'Încorporează făina, piperul și puțină sare. Compoziția trebuie să se lege ușor.', '2026-10-12T03:00:00.000Z', '2026-10-12T03:00:00.000Z'),
