  ('mancare-de-spanac:s1', 'mancare-de-spanac', 0, 'Spală spanacul în mai multe ape, taie-i cozile și toacă frunzele.', '2026-10-12T03:00:00.000Z', '2026-10-12T03:00:00.000Z'),
  ('mancare-de-spanac:s2', 'mancare-de-spanac', 1, 'Fierbe spanacul 5 minute în puțină apă cu sare, apoi scurge-l și strânge-l ușor.', '2026-10-12T03:00:00.000Z', '2026-10-12T03:00:00.000Z'),
  ('mancare-de-spanac:s3', 'mancare-de-spanac', 2, 'Călește ceapa tocată în ulei la foc mic, 5 minute, până se înmoaie.', '2026-10-12T03:00:00.000Z', '2026-10-12T03:00:00.000Z'),
  ('mancare-de-spanac:s4', 'mancare-de-spanac', 3, 'Adaugă făina și amestecă un minut, apoi pune spanacul și 200 ml de apă.', '2026-10-12T03:00:00.000Z', '2026-10-12T03:00:00.000Z'),
  ('mancare-de-spanac:s5', 'mancare-de-spanac', 4, 'Fierbe la foc mic 10 minute, amestecând din când în când.', '2026-10-12T03:00:00.000Z', '2026-10-12T03:00:00.000Z'),
  ('mancare-de-spanac:s6', 'mancare-de-spanac', 5, 'Adaugă usturoiul pisat, sare și piper, mai lasă 2 minute pe foc și servește, cu smântână dacă vrei.', '2026-10-12T03:00:00.000Z', '2026-10-12T03:00:00.000Z'),
  ('cartofi-taranesti:s1', 'cartofi-taranesti', 0, 'Încălzește cuptorul la 210°C.', '2026-10-12T03:00:00.000Z', '2026-10-12T03:00:00.000Z'),
  ('cartofi-taranesti:s2', 'cartofi-taranesti', 1, 'Curăță cartofii și taie-i felii groase sau căței. Taie ceapa pene și usturoiul felii.', '2026-10-12T03:00:00.000Z', '2026-10-12T03:00:00.000Z'),
  ('cartofi-taranesti:s3', 'cartofi-taranesti', 2, 'Amestecă cartofii cu ulei, boia, cimbru, sare și piper într-un castron.', '2026-10-12T03:00:00.000Z', '2026-10-12T03:00:00.000Z'),
