  ('cartofi-taranesti:s5', 'cartofi-taranesti', 4, 'Coace 30–35 de minute, amestecând o dată la jumătate, până se rumenesc.', '2026-10-12T03:00:00.000Z', '2026-10-12T03:00:00.000Z'),
  ('cartofi-taranesti:s6', 'cartofi-taranesti', 5, 'Adaugă usturoiul în ultimele 5 minute. Servește cu pătrunjel tocat și ardei iute, dacă vrei.', '2026-10-12T03:00:00.000Z', '2026-10-12T03:00:00.000Z'),
  ('linte-cu-legume:s1', 'linte-cu-legume', 0, 'Spală lintea și scurge-o. Taie ceapa mărunt, iar morcovii și țelina cubulețe.', '2026-10-12T03:00:00.000Z', '2026-10-12T03:00:00.000Z'),
  ('linte-cu-legume:s2', 'linte-cu-legume', 1, 'Călește ceapa în ulei 3 minute, apoi adaugă morcovii și țelina și mai călește 5 minute.', '2026-10-12T03:00:00.000Z', '2026-10-12T03:00:00.000Z'),
  ('linte-cu-legume:s3', 'linte-cu-legume', 2, 'Adaugă lintea, boia, dafinul și 1 litru de apă și fierbe la foc mic 25 de minute.', '2026-10-12T03:00:00.000Z', '2026-10-12T03:00:00.000Z'),
  ('linte-cu-legume:s4', 'linte-cu-legume', 3, 'Toarnă bulionul și fierbe încă 10 minute, până lintea e moale.', '2026-10-12T03:00:00.000Z', '2026-10-12T03:00:00.000Z'),
  ('linte-cu-legume:s5', 'linte-cu-legume', 4, 'Adaugă usturoiul pisat, sare și piper. Dacă vrei, pune oțetul la final.', '2026-10-12T03:00:00.000Z', '2026-10-12T03:00:00.000Z'),
  ('linte-cu-legume:s6', 'linte-cu-legume', 5, 'Scoate dafinul și servește fierbinte.', '2026-10-12T03:00:00.000Z', '2026-10-12T03:00:00.000Z'),
  ('fasole-batuta:s1', 'fasole-batuta', 0, 'Lasă fasolea la înmuiat în apă rece peste noapte, apoi scurge-o.', '2026-10-12T03:00:00.000Z', '2026-10-12T03:00:00.000Z'),
  ('fasole-batuta:s2', 'fasole-batuta', 1, 'Fierbe fasolea în apă proaspătă, la foc mic, 60–80 de minute, până se înmoaie complet. Sare abia la final.', '2026-10-12T03:00:00.000Z', '2026-10-12T03:00:00.000Z'),
  ('fasole-batuta:s3', 'fasole-batuta', 2, 'Scoate o parte din apa de fiert și zdrobește fasolea cu un tuci sau cu un blender de mână, adăugând apă până obții un piure gros.', '2026-10-12T03:00:00.000Z', '2026-10-12T03:00:00.000Z'),
  ('fasole-batuta:s4', 'fasole-batuta', 3, 'Adaugă usturoiul pisat, sare și piper.', '2026-10-12T03:00:00.000Z', '2026-10-12T03:00:00.000Z'),
  ('fasole-batuta:s5', 'fasole-batuta', 4, 'Taie ceapa felii subțiri și călește-o în ulei 8–10 minute, până se rumenește. La final, adaugă boia, dacă vrei.', '2026-10-12T03:00:00.000Z', '2026-10-12T03:00:00.000Z'),
  ('fasole-batuta:s6', 'fasole-batuta', 5, 'Pune fasolea în farfurii și toarnă ceapa călită deasupra.', '2026-10-12T03:00:00.000Z', '2026-10-12T03:00:00.000Z'),
  ('ciuperci-cu-smantana:s1', 'ciuperci-cu-smantana', 0, 'Fierbe 1 litru de apă cu sare, toarnă mălaiul în ploaie și amestecă 20–25 de minute, până se desprinde de pe oală.', '2026-10-12T03:00:00.000Z', '2026-10-12T03:00:00.000Z'),
  ('ciuperci-cu-smantana:s2', 'ciuperci-cu-smantana', 1, 'Șterge ciupercile cu un prosop umed și taie-le felii. Taie ceapa mărunt.', '2026-10-12T03:00:00.000Z', '2026-10-12T03:00:00.000Z'),
  ('ciuperci-cu-smantana:s3', 'ciuperci-cu-smantana', 2, 'Topește untul cu uleiul într-o tigaie și călește ceapa 3 minute.', '2026-10-12T03:00:00.000Z', '2026-10-12T03:00:00.000Z'),
  ('ciuperci-cu-smantana:s4', 'ciuperci-cu-smantana', 3, 'Adaugă ciupercile și gătește-le 8–10 minute la foc mare, până dispare zeama.', '2026-10-12T03:00:00.000Z', '2026-10-12T03:00:00.000Z'),
  ('ciuperci-cu-smantana:s5', 'ciuperci-cu-smantana', 4, 'Adaugă usturoiul pisat, sare și piper, apoi smântâna. Fierbe 3 minute la foc mic.', '2026-10-12T03:00:00.000Z', '2026-10-12T03:00:00.000Z'),
  ('ciuperci-cu-smantana:s6', 'ciuperci-cu-smantana', 5, 'Presară mărar tocat și servește peste mămăligă fierbinte.', '2026-10-12T03:00:00.000Z', '2026-10-12T03:00:00.000Z'),
  ('vinete-la-cuptor-cu-rosii:s1', 'vinete-la-cuptor-cu-rosii', 0, 'Încălzește cuptorul la 200°C.', '2026-10-12T03:00:00.000Z', '2026-10-12T03:00:00.000Z'),
  ('vinete-la-cuptor-cu-rosii:s2', 'vinete-la-cuptor-cu-rosii', 1, 'Taie vinetele în jumătăți pe lung. Crestează carnea în romburi, sărează-o și unge-o cu jumătate din ulei.', '2026-10-12T03:00:00.000Z', '2026-10-12T03:00:00.000Z'),
  ('vinete-la-cuptor-cu-rosii:s3', 'vinete-la-cuptor-cu-rosii', 2, 'Coace vinetele 20 de minute, cu fața în sus.', '2026-10-12T03:00:00.000Z', '2026-10-12T03:00:00.000Z'),
  ('vinete-la-cuptor-cu-rosii:s4', 'vinete-la-cuptor-cu-rosii', 3, 'Taie roșiile cubulețe și amestecă-le cu usturoiul pisat, oregano, sare, piper și restul de ulei.', '2026-10-12T03:00:00.000Z', '2026-10-12T03:00:00.000Z'),
  ('vinete-la-cuptor-cu-rosii:s5', 'vinete-la-cuptor-cu-rosii', 4, 'Pune roșiile peste vinete, presară cașcavalul ras și coace încă 15–20 de minute, până se rumenește.', '2026-10-12T03:00:00.000Z', '2026-10-12T03:00:00.000Z'),
  ('vinete-la-cuptor-cu-rosii:s6', 'vinete-la-cuptor-cu-rosii', 5, 'Servește cald, cu busuioc proaspăt deasupra.', '2026-10-12T03:00:00.000Z', '2026-10-12T03:00:00.000Z'),
  ('spaghete-bolognese:s1', 'spaghete-bolognese', 0, 'Toacă mărunt ceapa, morcovul și usturoiul.', '2026-10-12T03:00:00.000Z', '2026-10-12T03:00:00.000Z'),
  ('spaghete-bolognese:s2', 'spaghete-bolognese', 1, 'Încinge uleiul într-o tigaie adâncă și călește ceapa și morcovul 5 minute, apoi adaugă usturoiul încă un minut.', '2026-10-12T03:00:00.000Z', '2026-10-12T03:00:00.000Z'),
  ('spaghete-bolognese:s3', 'spaghete-bolognese', 2, 'Adaugă carnea tocată și sfărâm-o cu lingura. Prăjește-o 8–10 minute, până se rumenește.', '2026-10-12T03:00:00.000Z', '2026-10-12T03:00:00.000Z'),
  ('spaghete-bolognese:s4', 'spaghete-bolognese', 3, 'Pune pasta de tomate, roșiile din conservă strivite, oregano, sare și piper. Fierbe la foc mic 30 de minute, amestecând din când în când.', '2026-10-12T03:00:00.000Z', '2026-10-12T03:00:00.000Z'),
  ('spaghete-bolognese:s5', 'spaghete-bolognese', 4, 'Fierbe spaghetele în apă cu sare, după timpul de pe pachet, și scurge-le.', '2026-10-12T03:00:00.000Z', '2026-10-12T03:00:00.000Z'),
  ('spaghete-bolognese:s6', 'spaghete-bolognese', 5, 'Amestecă spaghetele cu sosul, servește cu parmezan ras și busuioc.', '2026-10-12T03:00:00.000Z', '2026-10-12T03:00:00.000Z'),
  ('paste-carbonara:s1', 'paste-carbonara', 0, 'Pune la fiert pastele în apă cu sare, după timpul de pe pachet.', '2026-10-12T03:00:00.000Z', '2026-10-12T03:00:00.000Z'),
  ('paste-carbonara:s2', 'paste-carbonara', 1, 'Taie baconul fâșii și prăjește-l fără ulei 5–6 minute, până devine crocant.', '2026-10-12T03:00:00.000Z', '2026-10-12T03:00:00.000Z'),
  ('paste-carbonara:s3', 'paste-carbonara', 2, 'Bate ouăle într-un bol cu parmezanul ras și mult piper.', '2026-10-12T03:00:00.000Z', '2026-10-12T03:00:00.000Z'),
  ('paste-carbonara:s4', 'paste-carbonara', 3, 'Scoate pastele cu o cană de apă de la fiert și scurge-le. Pune-le în tigaia cu bacon, pe foc stins.', '2026-10-12T03:00:00.000Z', '2026-10-12T03:00:00.000Z'),
  ('paste-carbonara:s5', 'paste-carbonara', 4, 'Toarnă amestecul de ouă peste paste și întoarce repede, adăugând câte o lingură de apă de la fiert până obții un sos cremos.', '2026-10-12T03:00:00.000Z', '2026-10-12T03:00:00.000Z'),
  ('paste-carbonara:s6', 'paste-carbonara', 5, 'Servește imediat, cu piper și parmezan deasupra.', '2026-10-12T03:00:00.000Z', '2026-10-12T03:00:00.000Z'),
  ('lasagna:s1', 'lasagna', 0, 'Călește ceapa și morcovul tocate în ulei 5 minute, apoi adaugă usturoiul și carnea tocată. Prăjește 10 minute.', '2026-10-12T03:00:00.000Z', '2026-10-12T03:00:00.000Z'),
  ('lasagna:s2', 'lasagna', 1, 'Adaugă roșiile strivite și pasta de tomate, sare și piper. Fierbe la foc mic 25 de minute.', '2026-10-12T03:00:00.000Z', '2026-10-12T03:00:00.000Z'),
  ('lasagna:s3', 'lasagna', 2, 'Pentru sosul alb, topește untul, adaugă făina și amestecă un minut. Toarnă laptele treptat, amestecând, și fierbe 5 minute până se îngroașă. Potrivește de sare și nucșoară.', '2026-10-12T03:00:00.000Z', '2026-10-12T03:00:00.000Z'),
  ('lasagna:s4', 'lasagna', 3, 'Încălzește cuptorul la 190°C. Unge o tavă cu puțin sos alb și pune un strat de foi.', '2026-10-12T03:00:00.000Z', '2026-10-12T03:00:00.000Z'),
  ('lasagna:s5', 'lasagna', 4, 'Așază alternativ sos de carne, sos alb, mozzarella tăiată și foi, în 3–4 straturi. Termină cu sos alb, mozzarella și parmezan ras.', '2026-10-12T03:00:00.000Z', '2026-10-12T03:00:00.000Z'),
  ('lasagna:s6', 'lasagna', 5, 'Coace 35–40 de minute, până se rumenește deasupra. Lasă 10 minute să se odihnească înainte de tăiat.', '2026-10-12T03:00:00.000Z', '2026-10-12T03:00:00.000Z'),
  ('pizza-de-casa:s1', 'pizza-de-casa', 0, 'Amestecă făina cu drojdia, zahărul și sarea. Adaugă uleiul și aproximativ 300 ml de apă caldă și frământă 8–10 minute, până aluatul e elastic.', '2026-10-12T03:00:00.000Z', '2026-10-12T03:00:00.000Z'),
  ('pizza-de-casa:s2', 'pizza-de-casa', 1, 'Acoperă aluatul și lasă-l la dospit 1 oră, până își dublează volumul.', '2026-10-12T03:00:00.000Z', '2026-10-12T03:00:00.000Z'),
  ('pizza-de-casa:s3', 'pizza-de-casa', 2, 'Pentru sos, strivește roșiile cu usturoiul, oregano, un praf de sare și puțin ulei.', '2026-10-12T03:00:00.000Z', '2026-10-12T03:00:00.000Z'),
  ('pizza-de-casa:s4', 'pizza-de-casa', 3, 'Încălzește cuptorul la 250°C, cu tava înăuntru. Împarte aluatul în două și întinde fiecare bucată subțire.', '2026-10-12T03:00:00.000Z', '2026-10-12T03:00:00.000Z'),
  ('pizza-de-casa:s5', 'pizza-de-casa', 4, 'Unge blatul cu sos, presară mozzarella tăiată și adaugă șunca sau ciupercile, dacă vrei.', '2026-10-12T03:00:00.000Z', '2026-10-12T03:00:00.000Z'),
  ('pizza-de-casa:s6', 'pizza-de-casa', 5, 'Coace fiecare pizza 10–12 minute, până se rumenește marginea. Presară busuioc proaspăt.', '2026-10-12T03:00:00.000Z', '2026-10-12T03:00:00.000Z'),
  ('chili-con-carne:s1', 'chili-con-carne', 0, 'Toacă ceapa, ardeiul și usturoiul.', '2026-10-12T03:00:00.000Z', '2026-10-12T03:00:00.000Z'),
  ('chili-con-carne:s2', 'chili-con-carne', 1, 'Încinge uleiul într-o oală și călește ceapa 4 minute, apoi adaugă ardeiul și usturoiul încă 2 minute.', '2026-10-12T03:00:00.000Z', '2026-10-12T03:00:00.000Z'),
  ('chili-con-carne:s3', 'chili-con-carne', 2, 'Adaugă carnea tocată și prăjește-o 10 minute, sfărâmând-o, până nu mai are zeamă.', '2026-10-12T03:00:00.000Z', '2026-10-12T03:00:00.000Z'),
  ('chili-con-carne:s4', 'chili-con-carne', 3, 'Pune boia afumată, chimenul, boia iute, pasta de tomate și roșiile strivite. Amestecă bine.', '2026-10-12T03:00:00.000Z', '2026-10-12T03:00:00.000Z'),
  ('chili-con-carne:s5', 'chili-con-carne', 4, 'Adaugă fasolea scursă, sare și piper. Fierbe la foc mic 25–30 de minute, amestecând din când în când.', '2026-10-12T03:00:00.000Z', '2026-10-12T03:00:00.000Z'),
  ('chili-con-carne:s6', 'chili-con-carne', 5, 'Servește fierbinte, cu o lingură de smântână deasupra.', '2026-10-12T03:00:00.000Z', '2026-10-12T03:00:00.000Z'),
  ('curry-de-pui:s1', 'curry-de-pui', 0, 'Taie pieptul de pui cubulețe și sărează-l ușor.', '2026-10-12T03:00:00.000Z', '2026-10-12T03:00:00.000Z'),
  ('curry-de-pui:s2', 'curry-de-pui', 1, 'Încinge uleiul și rumenește puiul 5 minute. Scoate-l din tigaie.', '2026-10-12T03:00:00.000Z', '2026-10-12T03:00:00.000Z'),
  ('curry-de-pui:s3', 'curry-de-pui', 2, 'În același ulei, călește ceapa tocată 4 minute, apoi adaugă usturoiul, ghimbirul și curry. Amestecă un minut.', '2026-10-12T03:00:00.000Z', '2026-10-12T03:00:00.000Z'),
  ('curry-de-pui:s4', 'curry-de-pui', 3, 'Pune roșiile strivite și puiul înapoi în tigaie. Fierbe la foc mic 15 minute.', '2026-10-12T03:00:00.000Z', '2026-10-12T03:00:00.000Z'),
  ('curry-de-pui:s5', 'curry-de-pui', 4, 'Adaugă smântâna și mai fierbe 5 minute. Potrivește de sare și piper.', '2026-10-12T03:00:00.000Z', '2026-10-12T03:00:00.000Z'),
  ('curry-de-pui:s6', 'curry-de-pui', 5, 'Fierbe orezul în apă cu sare, 12–15 minute, și scurge-l. Servește curry-ul peste orez, cu pătrunjel tocat.', '2026-10-12T03:00:00.000Z', '2026-10-12T03:00:00.000Z'),
  ('risotto-cu-ciuperci:s1', 'risotto-cu-ciuperci', 0, 'Dizolvă cuburile de supă în 1,2 l de apă și ține supa fierbinte, la foc mic.', '2026-10-12T03:00:00.000Z', '2026-10-12T03:00:00.000Z'),
  ('risotto-cu-ciuperci:s2', 'risotto-cu-ciuperci', 1, 'Taie ciupercile felii și călește-le în ulei, la foc mare, 6–7 minute, cu usturoiul zdrobit. Pune-le deoparte.', '2026-10-12T03:00:00.000Z', '2026-10-12T03:00:00.000Z'),
  ('risotto-cu-ciuperci:s3', 'risotto-cu-ciuperci', 2, 'Într-o oală, topește jumătate din unt și călește ceapa tocată mărunt 4 minute.', '2026-10-12T03:00:00.000Z', '2026-10-12T03:00:00.000Z'),
  ('risotto-cu-ciuperci:s4', 'risotto-cu-ciuperci', 3, 'Adaugă orezul și amestecă 2 minute. Toarnă vinul, dacă folosești, și lasă să se evapore.', '2026-10-12T03:00:00.000Z', '2026-10-12T03:00:00.000Z'),
  ('risotto-cu-ciuperci:s5', 'risotto-cu-ciuperci', 4, 'Adaugă supa câte o polonic, amestecând mereu și așteptând să fie absorbită. După 18–20 de minute orezul e moale, dar are încă miez fin.', '2026-10-12T03:00:00.000Z', '2026-10-12T03:00:00.000Z'),
  ('risotto-cu-ciuperci:s6', 'risotto-cu-ciuperci', 5, 'Stinge focul, adaugă ciupercile, untul rămas și parmezanul. Amestecă, potrivește de sare și piper și servește cu pătrunjel.', '2026-10-12T03:00:00.000Z', '2026-10-12T03:00:00.000Z'),
  ('paste-cu-ton-si-rosii:s1', 'paste-cu-ton-si-rosii', 0, 'Pune pastele la fiert în apă cu sare, după timpul de pe pachet.', '2026-10-12T03:00:00.000Z', '2026-10-12T03:00:00.000Z'),
  ('paste-cu-ton-si-rosii:s2', 'paste-cu-ton-si-rosii', 1, 'Între timp, călește ceapa tocată și usturoiul în ulei 3–4 minute.', '2026-10-12T03:00:00.000Z', '2026-10-12T03:00:00.000Z'),
  ('paste-cu-ton-si-rosii:s3', 'paste-cu-ton-si-rosii', 2, 'Adaugă roșiile strivite, oregano, sare și piper. Fierbe 8 minute la foc mediu.', '2026-10-12T03:00:00.000Z', '2026-10-12T03:00:00.000Z'),
  ('paste-cu-ton-si-rosii:s4', 'paste-cu-ton-si-rosii', 3, 'Scurge tonul și adaugă-l în sos, împreună cu măslinele și caperele, dacă folosești. Mai ține pe foc 2 minute.', '2026-10-12T03:00:00.000Z', '2026-10-12T03:00:00.000Z'),
  ('paste-cu-ton-si-rosii:s5', 'paste-cu-ton-si-rosii', 4, 'Scurge pastele și amestecă-le cu sosul. Presară pătrunjel tocat.', '2026-10-12T03:00:00.000Z', '2026-10-12T03:00:00.000Z'),
  ('salata-caesar-cu-pui:s1', 'salata-caesar-cu-pui', 0, 'Taie pâinea cubulețe, unge-le cu o lingură de ulei și prăjește-le în tigaie sau la cuptor, la 200°C, 6–8 minute, până sunt crocante.', '2026-10-12T03:00:00.000Z', '2026-10-12T03:00:00.000Z'),
  ('salata-caesar-cu-pui:s2', 'salata-caesar-cu-pui', 1, 'Condimentează pieptul de pui cu sare și piper și rumenește-l în restul de ulei, 5–6 minute pe fiecare parte. Lasă-l 5 minute să se odihnească, apoi taie-l felii.', '2026-10-12T03:00:00.000Z', '2026-10-12T03:00:00.000Z'),
  ('salata-caesar-cu-pui:s3', 'salata-caesar-cu-pui', 2, 'Pentru dressing, amestecă maioneza cu zeama de lămâie, usturoiul zdrobit, muștarul și jumătate din parmezan.', '2026-10-12T03:00:00.000Z', '2026-10-12T03:00:00.000Z'),
  ('salata-caesar-cu-pui:s4', 'salata-caesar-cu-pui', 3, 'Rupe salata în bucăți mari și amestec-o cu dressingul.', '2026-10-12T03:00:00.000Z', '2026-10-12T03:00:00.000Z'),
  ('salata-caesar-cu-pui:s5', 'salata-caesar-cu-pui', 4, 'Așază deasupra puiul, crutoanele și restul de parmezan. Servește imediat.', '2026-10-12T03:00:00.000Z', '2026-10-12T03:00:00.000Z'),
  ('hummus:s1', 'hummus', 0, 'Lasă năutul la înmuiat în apă rece 8–12 ore. Scurge-l.', '2026-10-12T03:00:00.000Z', '2026-10-12T03:00:00.000Z'),
  ('hummus:s2', 'hummus', 1, 'Fierbe năutul în apă proaspătă, la foc mic, 50–60 de minute, până se zdrobește ușor între degete. Păstrează o cană din apa de fiert.', '2026-10-12T03:00:00.000Z', '2026-10-12T03:00:00.000Z'),
  ('hummus:s3', 'hummus', 2, 'Prăjește susanul în tigaie uscată 2 minute, apoi pisează-l sau mixează-l fin.', '2026-10-12T03:00:00.000Z', '2026-10-12T03:00:00.000Z'),
  ('hummus:s4', 'hummus', 3, 'Mixează năutul scurs cu susanul, zeama de lămâie, usturoiul, chimenul și sarea. Adaugă apă de la fiert, câte o lingură, până obții o cremă fină.', '2026-10-12T03:00:00.000Z', '2026-10-12T03:00:00.000Z'),
  ('hummus:s5', 'hummus', 4, 'Pune hummusul într-un bol, toarnă uleiul deasupra și presară boia dulce. Se păstrează 4 zile la frigider.', '2026-10-12T03:00:00.000Z', '2026-10-12T03:00:00.000Z'),
  ('bowl-cu-pui-si-orez:s1', 'bowl-cu-pui-si-orez', 0, 'Încălzește cuptorul la 200°C. Amestecă sosul de soia cu mierea, usturoiul zdrobit și o lingură de ulei.', '2026-10-12T03:00:00.000Z', '2026-10-12T03:00:00.000Z'),
  ('bowl-cu-pui-si-orez:s2', 'bowl-cu-pui-si-orez', 1, 'Taie pieptul de pui felii groase și învelește-l în sos. Lasă-l 10 minute.', '2026-10-12T03:00:00.000Z', '2026-10-12T03:00:00.000Z'),
  ('bowl-cu-pui-si-orez:s3', 'bowl-cu-pui-si-orez', 2, 'Taie broccoli în buchete, morcovii rondele și ardeiul fâșii. Amestecă-le cu uleiul rămas, sare și piper.', '2026-10-12T03:00:00.000Z', '2026-10-12T03:00:00.000Z'),
  ('bowl-cu-pui-si-orez:s4', 'bowl-cu-pui-si-orez', 3, 'Pune puiul și legumele pe două tăvi și coace 20–25 de minute, întorcând o dată.', '2026-10-12T03:00:00.000Z', '2026-10-12T03:00:00.000Z'),
  ('bowl-cu-pui-si-orez:s5', 'bowl-cu-pui-si-orez', 4, 'Fierbe orezul în apă cu sare, 12–15 minute, și scurge-l.', '2026-10-12T03:00:00.000Z', '2026-10-12T03:00:00.000Z'),
  ('bowl-cu-pui-si-orez:s6', 'bowl-cu-pui-si-orez', 5, 'Împarte orezul, puiul și legumele în 4 caserole. Lasă-le să se răcească, apoi închide-le și pune-le la frigider, până la 4 zile. Presară susan înainte de mâncat.', '2026-10-12T03:00:00.000Z', '2026-10-12T03:00:00.000Z'),
  ('chiftele-la-cuptor-meal-prep:s1', 'chiftele-la-cuptor-meal-prep', 0, 'Încălzește cuptorul la 200°C.', '2026-10-12T03:00:00.000Z', '2026-10-12T03:00:00.000Z'),
  ('chiftele-la-cuptor-meal-prep:s2', 'chiftele-la-cuptor-meal-prep', 1, 'Amestecă carnea cu oul, ceapa rasă, usturoiul, pesmetul, pătrunjelul tocat, boia, sare și piper. Formează chiftele cât o nucă mare.', '2026-10-12T03:00:00.000Z', '2026-10-12T03:00:00.000Z'),
  ('chiftele-la-cuptor-meal-prep:s3', 'chiftele-la-cuptor-meal-prep', 2, 'Taie cartofii și morcovii bucăți mici, iar dovleceii cuburi mai mari. Amestecă-i cu uleiul, cimbrul, sare și piper.', '2026-10-12T03:00:00.000Z', '2026-10-12T03:00:00.000Z'),
  ('chiftele-la-cuptor-meal-prep:s4', 'chiftele-la-cuptor-meal-prep', 3, 'Întinde cartofii și morcovii pe o tavă mare și coace-i 15 minute.', '2026-10-12T03:00:00.000Z', '2026-10-12T03:00:00.000Z'),
  ('chiftele-la-cuptor-meal-prep:s5', 'chiftele-la-cuptor-meal-prep', 4, 'Adaugă dovleceii și chiftelele pe tavă și mai coace 25 de minute, întorcând chiftelele o dată, până sunt rumene.', '2026-10-12T03:00:00.000Z', '2026-10-12T03:00:00.000Z'),
  ('chiftele-la-cuptor-meal-prep:s6', 'chiftele-la-cuptor-meal-prep', 5, 'Lasă să se răcească și împarte în 4 caserole. Se păstrează la frigider 3–4 zile.', '2026-10-12T03:00:00.000Z', '2026-10-12T03:00:00.000Z'),
  ('quesadilla-cu-pui:s1', 'quesadilla-cu-pui', 0, 'Taie pieptul de pui fâșii subțiri și condimentează-l cu boia afumată, sare și piper.', '2026-10-12T03:00:00.000Z', '2026-10-12T03:00:00.000Z'),
  ('quesadilla-cu-pui:s2', 'quesadilla-cu-pui', 1, 'Rumenește puiul în jumătate din ulei, 6–7 minute. Adaugă ardeiul și ceapa tăiate fâșii și porumbul scurs și mai gătește 4 minute.', '2026-10-12T03:00:00.000Z', '2026-10-12T03:00:00.000Z'),
  ('quesadilla-cu-pui:s3', 'quesadilla-cu-pui', 2, 'Presară cașcaval pe jumătate din fiecare lipie, pune deasupra umplutura de pui și încă puțin cașcaval.', '2026-10-12T03:00:00.000Z', '2026-10-12T03:00:00.000Z'),
  ('quesadilla-cu-pui:s4', 'quesadilla-cu-pui', 3, 'Îndoaie lipiile în două.', '2026-10-12T03:00:00.000Z', '2026-10-12T03:00:00.000Z'),
  ('quesadilla-cu-pui:s5', 'quesadilla-cu-pui', 4, 'Rumenește fiecare quesadilla în tigaie încinsă cu puțin ulei, 2–3 minute pe fiecare parte, până se topește cașcavalul.', '2026-10-12T03:00:00.000Z', '2026-10-12T03:00:00.000Z'),
  ('quesadilla-cu-pui:s6', 'quesadilla-cu-pui', 5, 'Taie în triunghiuri și servește cu smântână.', '2026-10-12T03:00:00.000Z', '2026-10-12T03:00:00.000Z'),
  ('papanasi:s1', 'papanasi', 0, 'Strânge brânza într-un tifon și lasă-o 10 minute să se scurgă. Apoi freac-o printr-o strecurătoare sau zdrobește-o bine cu furculița.', '2026-10-12T03:00:00.000Z', '2026-10-12T03:00:00.000Z'),
  ('papanasi:s2', 'papanasi', 1, 'Amestecă brânza cu ouăle, grisul, zahărul, zahărul vanilat, sarea și jumătate din făină.', '2026-10-12T03:00:00.000Z', '2026-10-12T03:00:00.000Z'),
  ('papanasi:s3', 'papanasi', 2, 'Adaugă făina rămasă amestecată cu praful de copt, cât să iasă un aluat moale, care se lipește puțin de mâini.', '2026-10-12T03:00:00.000Z', '2026-10-12T03:00:00.000Z'),
  ('papanasi:s4', 'papanasi', 3, 'Formează 12 bile și fă câte o gaură în mijloc, ca la gogoși. Pune deoparte bucățile scoase și lipește-le deasupra ca o căciuliță.', '2026-10-12T03:00:00.000Z', '2026-10-12T03:00:00.000Z'),
  ('papanasi:s5', 'papanasi', 4, 'Încinge uleiul la foc mediu și prăjește papanașii 3–4 minute pe fiecare parte, până se rumenesc. Scurge-i pe hârtie de bucătărie.', '2026-10-12T03:00:00.000Z', '2026-10-12T03:00:00.000Z'),
  ('papanasi:s6', 'papanasi', 5, 'Servește călduți, cu smântână și dulceață deasupra.', '2026-10-12T03:00:00.000Z', '2026-10-12T03:00:00.000Z'),
  ('placinta-cu-mere:s1', 'placinta-cu-mere', 0, 'Amestecă făina cu praful de copt, untul rece tăiat cubulețe și 80 g de zahăr, frecând cu degetele până se face ca niște firimituri.', '2026-10-12T03:00:00.000Z', '2026-10-12T03:00:00.000Z'),
  ('placinta-cu-mere:s2', 'placinta-cu-mere', 1, 'Adaugă oul și smântâna și frământă repede un aluat neted. Împarte-l în două, înfășoară-l în folie și ține-l 30 de minute la frigider.', '2026-10-12T03:00:00.000Z', '2026-10-12T03:00:00.000Z'),
  ('placinta-cu-mere:s3', 'placinta-cu-mere', 2, 'Curăță merele și dă-le pe răzătoarea mare. Amestecă-le cu zahărul rămas, scorțișoara și zeama de lămâie.', '2026-10-12T03:00:00.000Z', '2026-10-12T03:00:00.000Z'),
  ('placinta-cu-mere:s4', 'placinta-cu-mere', 3, 'Încălzește cuptorul la 180°C. Întinde jumătate din aluat și tapetează o tavă de 24 cm, unsă cu unt.', '2026-10-12T03:00:00.000Z', '2026-10-12T03:00:00.000Z'),
  ('placinta-cu-mere:s5', 'placinta-cu-mere', 4, 'Pune merele peste aluat. Întinde restul aluatului și acoperă plăcinta, apoi înțeapă-l în câteva locuri cu furculița.', '2026-10-12T03:00:00.000Z', '2026-10-12T03:00:00.000Z'),
  ('placinta-cu-mere:s6', 'placinta-cu-mere', 5, 'Coace 40–45 de minute, până se rumenește. Lasă să se răcească și presară zahăr pudră.', '2026-10-12T03:00:00.000Z', '2026-10-12T03:00:00.000Z'),
  ('chec-cu-cacao:s1', 'chec-cu-cacao', 0, 'Încălzește cuptorul la 170°C și unge o formă de chec cu unt, apoi tapetează-o cu făină.', '2026-10-12T03:00:00.000Z', '2026-10-12T03:00:00.000Z'),
  ('chec-cu-cacao:s2', 'chec-cu-cacao', 1, 'Mixează untul cu zahărul și zahărul vanilat până devine cremos. Adaugă ouăle pe rând, mixând după fiecare.', '2026-10-12T03:00:00.000Z', '2026-10-12T03:00:00.000Z'),
  ('chec-cu-cacao:s3', 'chec-cu-cacao', 2, 'Amestecă făina cu praful de copt și un praf de sare, apoi încorporează-le în compoziție, alternând cu laptele.', '2026-10-12T03:00:00.000Z', '2026-10-12T03:00:00.000Z'),
  ('chec-cu-cacao:s4', 'chec-cu-cacao', 3, 'Împarte aluatul în două. Într-o jumătate amestecă cacaua.', '2026-10-12T03:00:00.000Z', '2026-10-12T03:00:00.000Z'),
  ('chec-cu-cacao:s5', 'chec-cu-cacao', 4, 'Toarnă în formă, pe rând, cu lingura, aluatul alb și cel cu cacao. Trage o furculiță prin aluat ca să se marmoreze.', '2026-10-12T03:00:00.000Z', '2026-10-12T03:00:00.000Z'),
  ('chec-cu-cacao:s6', 'chec-cu-cacao', 5, 'Coace 45–50 de minute. Verifică cu o scobitoare: trebuie să iasă uscată. Lasă checul 10 minute în formă, apoi scoate-l.', '2026-10-12T03:00:00.000Z', '2026-10-12T03:00:00.000Z'),
  ('orez-cu-lapte:s1', 'orez-cu-lapte', 0, 'Spală orezul sub jet de apă rece și scurge-l.', '2026-10-12T03:00:00.000Z', '2026-10-12T03:00:00.000Z'),
  ('orez-cu-lapte:s2', 'orez-cu-lapte', 1, 'Pune laptele la fiert într-o oală cu fundul gros, cu un praf de sare.', '2026-10-12T03:00:00.000Z', '2026-10-12T03:00:00.000Z'),
  ('orez-cu-lapte:s3', 'orez-cu-lapte', 2, 'Când dă în clocot, adaugă orezul și coboară focul. Fierbe 25–30 de minute, amestecând des ca să nu se prindă.', '2026-10-12T03:00:00.000Z', '2026-10-12T03:00:00.000Z'),
  ('orez-cu-lapte:s4', 'orez-cu-lapte', 3, 'Adaugă zahărul, zahărul vanilat și untul, dacă folosești. Mai fierbe 3–4 minute, până se îngroașă.', '2026-10-12T03:00:00.000Z', '2026-10-12T03:00:00.000Z'),
  ('orez-cu-lapte:s5', 'orez-cu-lapte', 4, 'Împarte în boluri și presară scorțișoară deasupra.', '2026-10-12T03:00:00.000Z', '2026-10-12T03:00:00.000Z'),
  ('salata-de-fructe:s1', 'salata-de-fructe', 0, 'Spală fructele. Curăță portocalele, kiwi și bananele și taie totul cubulețe, iar strugurii în jumătăți.', '2026-10-12T03:00:00.000Z', '2026-10-12T03:00:00.000Z'),
  ('salata-de-fructe:s2', 'salata-de-fructe', 1, 'Stropește merele și bananele cu zeama de lămâie, ca să nu se închidă la culoare.', '2026-10-12T03:00:00.000Z', '2026-10-12T03:00:00.000Z'),
  ('salata-de-fructe:s3', 'salata-de-fructe', 2, 'Amestecă fructele într-un bol mare, cu miere dacă vrei desertul mai dulce.', '2026-10-12T03:00:00.000Z', '2026-10-12T03:00:00.000Z'),
  ('salata-de-fructe:s4', 'salata-de-fructe', 3, 'Servește rece, cu iaurt și frunze de mentă. Mănâncă-o în aceeași zi.', '2026-10-12T03:00:00.000Z', '2026-10-12T03:00:00.000Z'),
  ('placinta-cu-branza:s1', 'placinta-cu-branza', 0, 'Încălzește cuptorul la 180°C și unge o tavă cu unt topit.', '2026-10-12T03:00:00.000Z', '2026-10-12T03:00:00.000Z'),
  ('placinta-cu-branza:s2', 'placinta-cu-branza', 1, 'Amestecă brânza cu ouăle, zahărul, zahărul vanilat, smântâna, un praf de sare, stafidele și coaja de lămâie.', '2026-10-12T03:00:00.000Z', '2026-10-12T03:00:00.000Z'),
  ('placinta-cu-branza:s3', 'placinta-cu-branza', 2, 'Pune două foi în tavă, ungându-le cu unt topit între ele.', '2026-10-12T03:00:00.000Z', '2026-10-12T03:00:00.000Z'),
  ('placinta-cu-branza:s4', 'placinta-cu-branza', 3, 'Întinde jumătate din umplutură, acoperă cu încă două foi unse cu unt, apoi pune restul de umplutură.', '2026-10-12T03:00:00.000Z', '2026-10-12T03:00:00.000Z'),
  ('placinta-cu-branza:s5', 'placinta-cu-branza', 4, 'Acoperă cu foile rămase, unse bine cu unt, și taie plăcinta în pătrate, doar prin foile de sus.', '2026-10-12T03:00:00.000Z', '2026-10-12T03:00:00.000Z'),
  ('placinta-cu-branza:s6', 'placinta-cu-branza', 5, 'Coace 35–40 de minute, până se rumenește. Lasă-o 10 minute să se odihnească înainte de servit.', '2026-10-12T03:00:00.000Z', '2026-10-12T03:00:00.000Z'),
  ('briose-cu-afine:s1', 'briose-cu-afine', 0, 'Încălzește cuptorul la 180°C și pune în forma de brioșe 12 forme de hârtie.', '2026-10-12T03:00:00.000Z', '2026-10-12T03:00:00.000Z'),
  ('briose-cu-afine:s2', 'briose-cu-afine', 1, 'Amestecă într-un bol făina, zahărul, zahărul vanilat, praful de copt și un praf de sare.', '2026-10-12T03:00:00.000Z', '2026-10-12T03:00:00.000Z'),
  ('briose-cu-afine:s3', 'briose-cu-afine', 2, 'Bate ouăle cu laptele și uleiul, apoi toarnă lichidul peste ingredientele uscate. Amestecă doar cât să se încorporeze, fără să frămânți.', '2026-10-12T03:00:00.000Z', '2026-10-12T03:00:00.000Z'),
  ('briose-cu-afine:s4', 'briose-cu-afine', 3, 'Tăvălește afinele prin puțină făină, apoi adaugă-le în aluat, cu grijă.', '2026-10-12T03:00:00.000Z', '2026-10-12T03:00:00.000Z'),
  ('briose-cu-afine:s5', 'briose-cu-afine', 4, 'Umple formele cu aluat, până la trei sferturi.', '2026-10-12T03:00:00.000Z', '2026-10-12T03:00:00.000Z'),
  ('briose-cu-afine:s6', 'briose-cu-afine', 5, 'Coace 20–22 de minute, până cresc și se rumenesc. Lasă-le 5 minute în tavă, apoi scoate-le pe un grătar.', '2026-10-12T03:00:00.000Z', '2026-10-12T03:00:00.000Z'),
  ('cozonac-de-casa:s1', 'cozonac-de-casa', 0, 'Încălzește 200 ml de lapte până e caldut și dizolvă drojdia cu o lingură de zahăr și două linguri de făină. Lasă 10 minute, până face spumă.', '2026-10-12T03:00:00.000Z', '2026-10-12T03:00:00.000Z'),
  ('cozonac-de-casa:s2', 'cozonac-de-casa', 1, 'Amestecă făina rămasă cu restul de zahăr din aluat, zahărul vanilat, un praf de sare, două ouă și drojdia activată. Frământă 10 minute, apoi adaugă untul moale și frământă încă 10 minute, până aluatul e elastic.', '2026-10-12T03:00:00.000Z', '2026-10-12T03:00:00.000Z'),
  ('cozonac-de-casa:s3', 'cozonac-de-casa', 2, 'Acoperă aluatul și lasă-l la dospit 1 oră și jumătate, într-un loc călduț, până își dublează volumul.', '2026-10-12T03:00:00.000Z', '2026-10-12T03:00:00.000Z'),
  ('cozonac-de-casa:s4', 'cozonac-de-casa', 3, 'Pentru umplutură, fierbe 100 ml de lapte cu zahărul, adaugă nucile, cacaua și esența de rom și amestecă. Lasă să se răcească.', '2026-10-12T03:00:00.000Z', '2026-10-12T03:00:00.000Z'),
  ('cozonac-de-casa:s5', 'cozonac-de-casa', 4, 'Întinde aluatul dreptunghi, unge-l cu umplutura, rulează-l strâns, împătură-l în două și răsucește-l. Pune-l într-o tavă de 30 cm, tapetată cu hârtie de copt. Lasă-l încă 45 de minute la dospit.', '2026-10-12T03:00:00.000Z', '2026-10-12T03:00:00.000Z'),
  ('cozonac-de-casa:s6', 'cozonac-de-casa', 5, 'Încălzește cuptorul la 180°C. Unge cozonacul cu oul bătut și coace 45–50 de minute. Dacă se rumenește prea repede, acoper-l cu folie de aluminiu.', '2026-10-12T03:00:00.000Z', '2026-10-12T03:00:00.000Z'),
  ('cozonac-de-casa:s7', 'cozonac-de-casa', 6, 'Lasă-l să se răcească în tavă înainte de tăiat.', '2026-10-12T03:00:00.000Z', '2026-10-12T03:00:00.000Z')
